DROP TABLE IF EXISTS `announcements`;
CREATE TABLE `announcements` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned DEFAULT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `content` text COLLATE utf8mb4_unicode_ci,
  `attachment` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `priority` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'normal',
  `is_pinned` tinyint(1) NOT NULL DEFAULT '0',
  `is_popup` tinyint(1) NOT NULL DEFAULT '0',
  `is_ticker` tinyint(1) NOT NULL DEFAULT '0',
  `status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `published_at` timestamp NULL DEFAULT NULL,
  `expires_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `announcements_user_id_foreign` (`user_id`),
  CONSTRAINT `announcements_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `announcements` (`id`, `user_id`, `title`, `content`, `attachment`, `priority`, `is_pinned`, `is_popup`, `is_ticker`, `status`, `published_at`, `expires_at`, `created_at`, `updated_at`, `deleted_at`) VALUES ('1', '1', 'Himbauan Aktivasi IKD', '<p>Dalam rangka mendukung transformasi layanan administrasi kependudukan yang lebih cepat, mudah, aman, dan efisien, masyarakat Kabupaten Dompu yang telah memiliki KTP-el diimbau untuk <strong>segera melakukan aktivasi Identitas Kependudukan Digital (IKD).</strong></p>', NULL, 'high', '1', '0', '1', 'published', '2026-07-23 12:06:00', NULL, '2026-07-23 12:06:48', '2026-07-27 17:30:42', NULL);

