INSERT INTO `banners` (`id`, `title`, `subtitle`, `image`, `image_mobile`, `url`, `url_target`, `type`, `button_text`, `is_active`, `sort_order`, `starts_at`, `ends_at`, `created_at`, `updated_at`, `deleted_at`) VALUES ('6', 'Yuk, aktifkan Identitas Kependudukan Digital (IKD) sekarang!', 'Dengan IKD, kamu bisa mengakses data kependudukanmu secara digital. Mudah dan praktis!', 'banners/f77d9ac4-f290-42c0-93c0-3cb73ccc87de.webp', NULL, NULL, '_self', 'hero', NULL, '1', '1', NULL, NULL, '2026-07-26 16:22:32', '2026-07-26 16:22:32', NULL);
INSERT INTO `banners` (`id`, `title`, `subtitle`, `image`, `image_mobile`, `url`, `url_target`, `type`, `button_text`, `is_active`, `sort_order`, `starts_at`, `ends_at`, `created_at`, `updated_at`, `deleted_at`) VALUES ('7', 'Perbaharui data KK melalui IKD', 'Pemutakhiran atau pembaharuan data Kartu Keluarga (KK) kini dapat dilakukan secara praktis melalui aplikasi Identitas Kependudukan Digital (IKD)', 'banners/119f8027-f1e7-4a73-8cc4-8365f9a2f83f.webp', NULL, NULL, '_self', 'hero', NULL, '1', '1', NULL, NULL, '2026-07-26 16:31:17', '2026-07-26 16:31:17', NULL);
INSERT INTO `banners` (`id`, `title`, `subtitle`, `image`, `image_mobile`, `url`, `url_target`, `type`, `button_text`, `is_active`, `sort_order`, `starts_at`, `ends_at`, `created_at`, `updated_at`, `deleted_at`) VALUES ('8', 'Layanan Online', 'Siapkan dokumen Anda dan akses layanannya sekarang juga melalui komputer atau smartphone Anda di sanai-dukcapil.dompukab.go.id', 'banners/016dd5c2-98fc-4106-aee9-886b5f18f864.webp', NULL, NULL, '_self', 'hero', NULL, '1', '1', NULL, NULL, '2026-07-27 02:11:37', '2026-07-27 02:19:44', NULL);

