DROP TABLE IF EXISTS `complaint_replies`;
CREATE TABLE `complaint_replies` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `complaint_id` bigint unsigned NOT NULL,
  `user_id` bigint unsigned DEFAULT NULL,
  `message` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `type` enum('admin_reply','status_change','note') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'admin_reply',
  `old_status` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `new_status` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_visible_to_submitter` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Internal notes are hidden from public tracker',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `complaint_replies_user_id_foreign` (`user_id`),
  KEY `complaint_replies_complaint_id_created_at_index` (`complaint_id`,`created_at`),
  CONSTRAINT `complaint_replies_complaint_id_foreign` FOREIGN KEY (`complaint_id`) REFERENCES `complaints` (`id`) ON DELETE CASCADE,
  CONSTRAINT `complaint_replies_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

