DROP TABLE IF EXISTS `complaints`;
CREATE TABLE `complaints` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `ticket_number` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `submitter_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `submitter_phone` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `submitter_email` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_anonymous` tinyint(1) NOT NULL DEFAULT '0',
  `complaint_category_id` bigint unsigned DEFAULT NULL,
  `subject` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `message` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `attachment_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Optional supporting file upload',
  `attachment_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` enum('pending','in_review','in_progress','resolved','rejected') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `captcha_token` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ip_address` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `user_agent` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `read_at` timestamp NULL DEFAULT NULL COMMENT 'When admin first opened it',
  `resolved_at` timestamp NULL DEFAULT NULL,
  `assigned_to` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `complaints_ticket_number_unique` (`ticket_number`),
  KEY `complaints_complaint_category_id_foreign` (`complaint_category_id`),
  KEY `complaints_assigned_to_foreign` (`assigned_to`),
  KEY `complaints_status_created_at_index` (`status`,`created_at`),
  KEY `complaints_ticket_number_index` (`ticket_number`),
  CONSTRAINT `complaints_assigned_to_foreign` FOREIGN KEY (`assigned_to`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `complaints_complaint_category_id_foreign` FOREIGN KEY (`complaint_category_id`) REFERENCES `complaint_categories` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `complaints` (`id`, `ticket_number`, `submitter_name`, `submitter_phone`, `submitter_email`, `is_anonymous`, `complaint_category_id`, `subject`, `message`, `attachment_path`, `attachment_name`, `status`, `captcha_token`, `ip_address`, `user_agent`, `read_at`, `resolved_at`, `assigned_to`, `created_at`, `updated_at`) VALUES ('2', 'DKP-2026-EOEGVO', 'Anonim', NULL, NULL, '1', NULL, 'tes anonim', 'sadjsakjdsaj djsajdasj dsajdjsadj', 'complaints/attachments/eZtuNbVGNhLk9uBdDrAkzqcgil3wcmspA2qFVaub.png', 'Gemini_Generated_Image_b5q5kcb5q5kcb5q5.png', 'resolved', NULL, '127.0.0.1', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/150.0.0.0 Safari/537.36', '2026-07-27 16:16:17', '2026-07-27 18:10:45', NULL, '2026-07-27 16:16:03', '2026-07-27 18:10:45');

DROP TABLE IF EXISTS `demographic_datasets`;
CREATE TABLE `demographic_datasets` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `kecamatan_id` bigint unsigned DEFAULT NULL,
  `region_level` enum('regency','district','village') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'regency',
  `region_code` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'BPS region code: 5205=Kab.Dompu, 520501=Kec.Dompu, …',
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `year` smallint unsigned NOT NULL,
  `semester` tinyint unsigned NOT NULL DEFAULT '1' COMMENT '1: Semester 1 (Juni), 2: Semester 2 (Desember)',
  `type` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'population',
  `file_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Uploaded PDF/Excel source file',
  `file_size` bigint unsigned NOT NULL DEFAULT '0',
  `file_type` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` enum('draft','published') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `published_at` timestamp NULL DEFAULT NULL,
  `data_json` json DEFAULT NULL COMMENT 'Structured chart-ready data',
  `notes` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `demographic_datasets_kecamatan_id_foreign` (`kecamatan_id`),
  KEY `demographic_datasets_year_type_status_index` (`year`,`type`,`status`),
  KEY `demographic_datasets_year_semester_type_status_index` (`year`,`semester`,`type`,`status`),
  KEY `idx_region_period_status` (`region_level`,`region_code`,`year`,`semester`,`status`),
  CONSTRAINT `demographic_datasets_kecamatan_id_foreign` FOREIGN KEY (`kecamatan_id`) REFERENCES `kecamatans` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=23 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

