INSERT INTO `faqs` (`id`, `question`, `answer`, `category`, `sort_order`, `is_published`, `created_at`, `updated_at`, `deleted_at`) VALUES ('8', 'Frequently Asked Question (FAQ)', '<h1>Frequently Asked Question</h1>				
