  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `file_folders_created_by_foreign` (`created_by`),
  KEY `file_folders_parent_id_index` (`parent_id`),
  CONSTRAINT `file_folders_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
