DROP TABLE IF EXISTS `innovations`;
CREATE TABLE `innovations` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `icon` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Emoji or icon name',
  `color` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '#4f46e5',
  `description` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `content` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Detailed rich text explaining the innovation',
  `youtube_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Explainer YouTube video embed link',
  `sort_order` smallint unsigned NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `innovations_slug_unique` (`slug`)
) ENGINE=InnoDB AUTO_INCREMENT=31 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `innovations` (`id`, `title`, `slug`, `icon`, `color`, `description`, `content`, `youtube_url`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES ('1', '\"Lacak Mantan\"', 'lacak-mantan', '🚐', '#4f46e5', 'Layanan Cepat dan Khusus Masyarakat Rentan Adminduk', '<p style=\"text-align: left;\"><strong>Layanan Cepat dan Khusus bagi Masyarakat Rentan Adminduk atau Lacak Mantan</strong> ini adalah salah satu program inovasi unggulan Dinas Kependudukan dan Pencatatan Sipil Kabupaten Dompu. Program inovasi ini memfokuskan kepada pemberian layanan yang cepat dan dikhususkan kepada masyarakat rentan adminduk seperti penyandang disabilitas, Orang dengan Gangguan Jiwa, dan atau Warga Lanjut Usia. Program ini dilatarbelakangi oleh sulitnya masyarakat rentan adminduk untuk melakukan pengurusan administrasi kependudukannya karena keterbatasan masyarakat untuk mengakses pelayanan Dinas Dukcapil Dompu. Meskipun di Dinas Dukcapil Dompu sendiri telah memiliki fasilitas untuk melayani masyarakat rentan adminduk di Kantor Dinas Dukcapil, sangat jarang ada masyarakat rentan adminduk yang datang untuk mengurus dokumen adminduknya. Hal ini tentunya dikarenakan keterbatasan yang dimiliki sebagai kelompok rentan.</p><p style=\"text-align: left;\">Oleh sebab itu, Dinas Dukcapil Dompu sejak tahun 2021 sudah memulai inovasi ini dengan datang ke alamat tempat tinggal masyarakat rentan adminduk dan memberikan pelayanan langsung sesuai kebutuhan masyarakat. Meskipun mendapat banyak kendala di lapangan seperti masyarakat rentan yang sulit diajak bekerjasama karena keterbatasannya, kesulitan melakukan perekaman, lokasi-lokasi masyarakat yang cukup jauh, tidak menyurutkan pelayanan Lacak Mantan ini untuk tetap berjalan. Pelayanan ini memastikan bahwa setiap orang atau penduduk yang ada di Kabupaten Dompu telah memiliki identitas resmi atau bukti diri yang sah tanpa terkecuali. Terutama masyarakat rentan adminduk seperti penyandang disabilitas, ODGJ, atau Warga Lansia sangat membutuhkan dokumen adminduk berupa KTP-EL agar bisa mendapatkan pelayanan publik seperti saat pengurusan pengobatan di Rumah Sakit atau agar dapat diikutsertakan dalam bantuan sosial dari pemerintah.</p><p style=\"text-align: left;\">Inovasi ini disambut baik oleh masyrakat Dompu, mengingat bahwa kini hampir setiap harinya Tim Lacak Mantan turun untuk memberikan pelayanan sesuai dengan permintaan dari masyarakat selaku anggota keluarga dari masyarakat rentan adminduk. Program inovasi ini akan mempermudah masyarakat rentan adminduk untuk memiliki dokume kependudukan sesuai dengan Permendagri Nomor 96 Tahun 2019. Tentunya program ini dirancang sebagai program pelayanan yang membahagiakan masyarakat. Karena semua orang berhak memiiki dokumen kependudukan.</p>', 'https://www.youtube.com/embed/dR2hHR55dNA', '1', '1', '2026-07-20 05:39:56', '2026-07-24 00:31:15');
INSERT INTO `innovations` (`id`, `title`, `slug`, `icon`, `color`, `description`, `content`, `youtube_url`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES ('2', '\"Kasama Rai\"', 'kasama-rai', '👶', '#10b981', 'Kerjasama Percepatan Dokumen Akta Kelahiran dan Kartu Identitas Anak', '<p style=\"text-align: left;\">Program inovasi Kasama Rai adalah program Kerjasama Percepatan Dokumen Akta Kelahiran dan KIA yang bertujuan meningkatkan pelayanan terhadap dokumen kependudukan berupa Akta Kelahiran dan Kartu Identitas Anak (KIA) dimana kedua dokumen ini masih memiliki capaian yang rendah secara nasional. Kerjasama ini dilakukan dengan Dinas Dikpora Kabupaten Dompu selaku OPD yang bertanggungjawab dan berwenang melaksanakan urusan pemerintah di bidang pendidikan.<br>Saat ini, masih banyak anak di Kabupaten Dompu yang identitasnya tidak tercatat dalam akta kelahiran, maka secara hukum keberadaannya dianggap tidak ada. Kondisi ini tidak hanya karena ketidaktahuan masyarakat akan arti penting akta kelahiran, namun juga karena biaya yang tidak terjangkau untuk transportasi saat hendak melakukan pengurusan, serta prosedur yang dianggap panjang dan sulit, dan juga ketakutan akan merasa terdiskriminasi jika berbeda dari kelompok mayoritas (Anak Luar Kawin). Selain Akta Kelahiran, kepemilikan Kartu Identitas Anak dengan jumlah anak yang ada di Kabupaten Dompu masih belum menyentuh angka 40%, yang artinya masih lebih dari sebagian anak di Kabupaten Dompu belum memiliki KIA. Sementara Kartu Identitas Anak sudah mulai diwajibkan secara nasional sebagai identitas resmi untuk anak di bawah 17 tahun sesuai dengan Peraturan Kementerian Dalam Negeri No. 2 Tahun 2016 tentang Kartu Identitas Anak. Apalagi untuk saat ini, akta kelahiran dan Kartu Identitas Anak menjadi salah satu persyaratan kelengkapan saat mendaftar sekolah.<br>Berdasarkan hal diatas, maka Dinas Dukcapil Dompu mulaimelakukan kerjasama denganberbagai pihak termasuk sekolah-sekolah, instansi, serta lembaga-lembaga di kab. Dompu. Dalam mekanismenya, Dinas Dukcapil Dompu bekerjasama dengan sekolah-sekolah yang ada di Kabupaten Dompu terutama SD dan SMP dalam pembuatan Akta Kelahiran dan KIA bagi siswa-siswi secara kolektif. Pengurusan Akta Kelahiran dan KIA secara kolektif ini dilakukan oleh sekolah, dimana setiap guru wali kelas mengumpulkan bahan-bahan persyaratan bagi anak didiknya dan dikumpulkan secara kolektif dan diantarkan ke Dinas Dukcapil Dompu yang nantinya akan dikerjakan oleh tim percepatan. Selain itu, kerjasama ini juga dapat dilakukan on the spot saat terdapat pelayanan keliling ke sekolah-sekolah untuk pelayanan KIA dan Akta Kelahiran bagi anak serta saat pelayanan mobile dengan asas kerjasama dengan beberapa lembaga atau instansi seperti DP3A Kabupaten Dompu atau Tim PKK Kabupaten Dompu.</p>', NULL, '2', '1', '2026-07-20 05:39:56', '2026-07-24 00:26:43');
INSERT INTO `innovations` (`id`, `title`, `slug`, `icon`, `color`, `description`, `content`, `youtube_url`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES ('3', '\"Oi Marai\"', 'oi-marai', '🌐', '#ec4899', 'Layanan penerbitan 3 dokumen adminduk sekaligus (KK baru orang tua, KK baru mertua, dan KTP status kawin) bagi pasangan pengantin baru setelah akad nikah.', '<p style=\"text-align: left;\">Dinas Kependudukan dan Pencatatan Sipil Kabupaten Dompu terus berbenah untuk dapat melayani pengurusan administrasi kependudukan bagi masyarakat Kabupaten Dompu secara optimal. Berbagai upaya yang sedang dilakukan, diantaranya adalah melakukan inovasi “Layanan Online Dokumen Kependudukan Tanpa Antri” atau disebut juga sebagai program Oi Marai. Layanan online ini merupakan layanan pengurusan adminsitrasi kependudukan berbasis website aplikasi dimana masyarakat dapat mengurus administrasi kependudukannya melalui internet di Handphone ataupun di komputer dan laptop. Masyarakat dapat melakukan pengurusan administrasi kependudukan dari rumah, kantor, atau darimana saja tanpa harus datang dan mengantri ke kantor Dinas Kependudukan dan Pencatatan Sipil Kabupaten Dompu. Dengan hadirnya program ini, masyarakat diharapkan dapat mengurus dokumen adminduknya tanpa terbatas jarak dan waktu, sehingga tidak perlu mengantri dan mendapatkan proses yang lancar seperti air yang mengalir (Oi Marai).</p><p style=\"text-align: left;\">Di Kabupaten Dompu, masih banyak masyarakat yang belum memiliki dokumen kependudukan atau belum melakukan pemutakhiran datanya ke Dinas Dukcapil Dompu. Keterbatasan jarak menjadi salah satu alasan bagi mayoritas masyarakat di Kabupaten Dompu belummelakukan pengurusan administrasi kependudukannya. Letak beberapa desa di kecamatan-kecamatan di Kabupaten Dompu termasuk cukup jauh dan membutuhkan waktu yang lama serta biaya yang tidak sedikit untuk mengurus administrasi kependudukan. Selain itu juga, keterbatasan waktu terutama bagi para pekerja kantoran, anak sekolah, ibu rumah tangga yang mengurus anak, juga menjadi alasan sulitnya masyarakat mengurus administrasi kependudukan. Sehingga, pada akhirnya masyarakat lebih memilih menggunakan jasa calo yang membutuhkan bayaran untuk jasanya sementara resiko kesalahan data saat pengurusan dokumen juga cukup tinggi jika tidak diurus sendiri. Maka dari itu, Layanan online ini hadir untuk menyelesaikan permasalahan-permasalahan itu.<br>Layanan online ini dapat diakses melalui situs <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary-600 dark:text-primary-400 font-bold underline\" href=\"https://dukcapil.dompu.online/\">https://sanai-dukcapil.dompukab.go.id/</a> yang dapat dibuka kapan saja dan dimana saja. Masyarakat yang ingin mengurus dokumen kependudukan, cukup mengakses situs diatas, menyiapkan bahan dan dokumen yang disyaratkan, membuat akun, lalu mengupload bahanbahan yang diminta sesuai petunjuk. DI dalam situs tersebut, terdapat status pengajuan yang dapat dipantau prosesnya. Adapun dokumen kependudukan yang diurus nantinya dapat dikirim berbentuk PDF atau dapat di-unduh (download) di situs web atau bahkan dapat diambil sendiri ke Kantor Dukcapil Dompu setelah dokumen adminduk selesai diproses. Program ini juga bertujuan sebagai solusi untuk mengatasi antrian panjang saat mengurus adminduk secara tatap muka di kantor Dinas Dukcapil Dompu.</p>', 'https://www.youtube.com/embed/mV8kRfEfbBo', '3', '1', '2026-07-20 05:39:56', '2026-07-24 00:28:48');
INSERT INTO `innovations` (`id`, `title`, `slug`, `icon`, `color`, `description`, `content`, `youtube_url`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES ('4', '\"Jebol Lagi\"', 'jebol-lagi', '🚀', '#f59e0b', 'Jemput Bola Layanan GISA (Gerakan Indonesia Sadar Adminduk)', '<p style=\"text-align: justify;\">Jarak yang jauh serta harus mengeluarkan biaya transportasi dan akomodasi menuju Dinas Dukcapil Dompu membuat sebagian masyarakat memilih untuk tidak mengurus dokumen administrasi kependudukannya . Program Jebol Lagi atau Jemput Bola Layanan GISA (Gerakan Sadar Adminduk) merupakan inovasi Dinas Kependudukan dan Pencatatan Sipil Kabupaten Dompu untuk mensukseskan Gerakan Indonesia Sadar Administrasi Kependudukan.&nbsp; Program Jebol Lagi hadir di tengah-tengah masyarakat dengan sistem jemput bola atau secara langsung mendatangi masyarakat di desa-desa, sekolah-sekolah, ataupun lembaga yang ada di Kabupaten Dompu.</p><p style=\"text-align: justify;\">Adapun pelayanan yang diberikan antara lain yaitu sosialisasi administrasi kependudukan, perekaman KTP-EL, penerbitan Kartu Keluarga, Akta Kelahiran, Akta Kematian, Akta Perkawinan, SKPWNI, dan juga Kartu Identitas Anak (KIA). Inovasi pelayanan ini telah berlangsung sejak tahun 2018 dan masih dilakukan secara berkala dan bertahp di desa-desa di Kabupaten Dompu. Program ini bertujuan untuk mendekatkan serta mempercepatt pelayanan administrasi kependudukan dan pencatatan sipil dengan cara mendatangi masyarakat dan melaksanakan pelayanan di tempat. Dengan hadirnya program ini, diharapkan masyarakat yang berdomisili jauh, tidak memiliki kemampuan secara fisik atau materil untuk mendatangi Dukcapil, dapat terbantu layanan administrasi kependudukannya. Pelayanan dilakukan dengan cara berkeliling ke kecamatan, desa-desa, sekolah, bahkan lembaga permasyarakatan yang membutuhkan pelayanan administrasi kependudukan.</p><p style=\"text-align: justify;\">Tujuan dari adanya program ini berdasar dari pentingnya administrasi kependudukan, mengingat bahwa adminduk merupakan dasar bagi semua pelayanan publik seperti bantuan sosial, kesehatan, dan pendidikan, yang mana selalu membutuhkan Nomor Induk Kependudukan untuk dapat mengaksesnya. Seain itu, pelayanan jemput bola ini juga diperuntukkan bagi kelompok rentan adminduk seperti penyandang disabilitas, orang sakit keras, Orang Dengan Gangguan Jiwa, dan juga orang Lanjut Usia yang akan sangat sulit mendatangi kantor Dukcapil.</p><p style=\"text-align: justify;\">Selain itu juga, pelayanan jemput bola diselenggrakan di desa-desa yang akan menyambut pilkades serentak yang tentunya membutuhkan administrasi kependudukan bagi masyarakat di dalam prosesnya. Pelayana ini juga berlaku bagi desa-desa yang telah melakukan pemekaran desa yang mmebuat warganya harus mengganti alamat secara massal karena dampak dari perubahan alamat karena terjadinya pemekaran wilayah.</p>', NULL, '4', '1', '2026-07-20 05:39:56', '2026-07-24 00:30:51');
INSERT INTO `innovations` (`id`, `title`, `slug`, `icon`, `color`, `description`, `content`, `youtube_url`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES ('23', '\"Rela Dicek Malam\"', 'rela-dicek-malam', '🔔', '#4f46e5', 'Rekam Langsung dicetak Malam', '<p>Program inovasi RELA DICEK MALAM adalah salah satu inovasi dari Dinas Kependudukan dan Pencatatan Sipil Kabupaten Dompu dalam rangka memenuhi target rekam data bagi Wajib KTP Pemula. Inovasi ini dilatarbelakangi oleh masih banyaknya masyarakat yang enggan atau tidak mau antri untuk datang langsung ke Dukcapil dalam rangka membuat KTP baru. Tim inovasimenetapkan titik lokasi yang paling sering dikunjungi oleh masyarakat khususnya pemuda-pemudi yang telah berusia 17 tahun atau lebih. Pelayanan Perekaman dan Pencetakan KTP-EL ini dilakukan malam hari di luar jam pelayanan kantor dan berada di lokasi keramaian, salah satunya adalah di Taman Kota Dompu.</p><p style=\"text-align: justify;\">Program ini menyasar pada warga yang kesulitan mendatangi tempat layanan pada pagi maupun siang hari, terutama remaja yang merupakan penduduk Wajib KTP yang telah berusia 17 tahun yang mana diantaranya merupakan anak sekolah. Jam belajar di Sekolah dan jam pelayanan di Kantor Dukcapil yang cenderung sama, membuat anak-anak sekolah kesulitan untuk datang ke Dukcapil karena harus mengantongi ijin dari sekolah terlebih dahulu. Maka dari itu, penambahan jam layanan hingga malam hari di dalam program ini diperuntukkan agar mereka dapat melakukan perekaman KTP-EL dan mendapatkan KTP-EL yang dicetak di hari yang sama. Bagi para remaja yang ingin merekam KTP-EL, cukup membawa salinan Kartu Keluarganya sebagai syarat dilakukannya perekaman. Tidak hanya remaja yang telah berusia 17 tahun, unntuk anak-anak yang telah berusia 16 tahun juga sudah bisa melakukan perekaman dengan membawa salinan Kartu Keluarganya. Sehingga, saat mereka telah berusia 17 tahun, mereka dapat mencetak KTP-EL tanpa melakukan perekaman lagi.</p><p style=\"text-align: justify;\">Program inovasi ini dilakukan di waktu-waktu tertentu, terutama saat menjelang PEMILU, baik itu Pemilihan Presiden/Wakil Presiden, DPR, DPD, Gubernur/Wakil Gubernur, DPRD Prov, Bupati/Wabup, DPRD Kabupaten, dan juga pada saat Pemilihan Kepala Desa di Kabupaten Dompu berlangsung. Program ini telah dilakukan sejak tahun 2019 dan masih dilakukan hingga saat ini. Dan Program ini hanya diberlakukan untuk pelayanan perekaman dan Pencetakan KTP-EL saja, sehingga untuk masyarakat yang datang untuk memperbarui KK atau membuat Akta Kelahiran tidak bisa diperuntukkan di program ini.</p>', 'https://www.youtube.com/embed/wXtP32xEpL8', '5', '1', '2026-07-24 00:36:32', '2026-07-24 00:36:32');
INSERT INTO `innovations` (`id`, `title`, `slug`, `icon`, `color`, `description`, `content`, `youtube_url`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES ('24', '\"Gebyar Idaman\"', 'gebyar-idaman', '🎯', '#4f46e5', 'Gerakan Bersama Pelayanan Adminduk dan Penerbitan Identitas Anak Lima Sasaran', '<p style=\"text-align: left;\">Berangkat dari Dinas Kependudukan dan Pencatatan Sipil Kab. Dompu yang diharuskan membuat pelaporan sebagai tindak lanjut dari Koordinasi Pemenuhan Laporan Rencana Aksi HAM 4 Tahun 2023 kepada Sekretariat Daerah, maka inovasi “Gebyar Idaman” perlu diimplementasikan di Dinas Kependudukan dan Pencatatan Sipil Kabupaten Dompu. “Gebyar Idaman” merupakan inovasi untuk melakukan pelayanan administrasi kependudukan bagi anak yang termasuk dalam lima kelompok sasaran Aksi HAM, yaitu Anak penghuni panti asuhan/sosial, anak penghayat kepercayaan, minoritas agama, dan kelompok masyarakat adat (KMA), anak dengan penyakit tertentu (HIV/AIDS), anak berhadapan dengan hukum (ABH), dan anak luar kawin.</p><p style=\"text-align: left;\">Adapun tujuan inovasi ini adalah mendorong peningkatan kinerja Dinas Dukcapil Kab. Dompu, meningkatkan jangkauan layanan pemberian dokumen kependudukan kepada anak-anak dari lima kelompok sasaran aksi ham, meningkatkan Perjanjian Kerjasama antar OPD dengan Dinas Dukcapil Kab. Dompu, dan sebagai bahan pelaporan Rencana Aksi HAM disetiap tahun anggaran.</p><p style=\"text-align: left;\">Prosedur kerja dalam pelaksanaan inovasi “Gebyar Idaman”, prosedur layanan yang akan dilakukan adalah sebagai berikut:&nbsp;Dinas Kependudukan dan Pencatatan Sipil melakukan rapat koordinasi terkait permintaan data dan permintaan kerjasama dengan OPD terkait yang menangani 5 kelompok sasaran. Adapun instansi atau OPD terkait adalah:&nbsp;Anak Panti Asuhan/Sosial: Dinas Sosial dan Lembaga/Yayasan Panti Asuhan;&nbsp;Anak dengan penyakit tertentu (HIV/AIDS): Dinas Kesehatan dan RSUD;&nbsp;Anak Berhadapan Hukum: Lapas IIB Dompu (terdapat beberapa tahanan titipan anak dan tahanan Perlindungan Anak, serta tahanan anak yang menunggu putusan pengadilan);&nbsp;Anak Luar Kawin: DP3A dan Kantor DesaKel (saat pelayanan mobile);&nbsp;anak penghayat kepercayaan, minoritas agama, dan kelompok masyarakat adat (KMA): Tempat ibadah anak anak penghayat kepercayaan, minoritas agama, dan kelompok masyarakat adat, seperti gereja dan banjar</p><p style=\"text-align: left;\">Dinas Kependudukan dan Pencatatan Sipil Kab. Dompu membuat dan menandatangani Perjanjian Kerjasama dengan OPD yang disepakati.&nbsp;Setelah mendapat data dan perjanjian kerjasama, Dinas Dukcapil dan OPD terkait bersurat mengenai informasi pelayanan yang akan dilakukan.&nbsp;Melakukan pelayanan administrasi kependudukan bagi anak yang termasuk dalam lima kelompok sasaran Aksi HAM, yaitu Anak penghuni panti asuhan/sosial, anak penghayat kepercayaan, minoritas agama, dan kelompok masyarakat adat (KMA), anak dengan penyakit tertentu (HIV/AIDS), anak berhadapan dengan hukum (ABH), dan anak luar kawin dengan output dokumen kependudukan berupa Akta Kelahiran, KIA, dan atau Kartu Keluarga dengan sistem jemput bola atau pelayanan mobile.</p>', NULL, '6', '1', '2026-07-24 00:38:22', '2026-07-24 00:38:22');
INSERT INTO `innovations` (`id`, `title`, `slug`, `icon`, `color`, `description`, `content`, `youtube_url`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES ('25', '\"Dukcapil Goes to School\"', 'dukcapil-goes-to-school', '🏫', '#4f46e5', 'Jemput bola perekaman KTP el di Sekolah', '<p style=\"text-align: left;\">Dalam rangka melakukan pemenuhan hak anak, Dinas Kependudukan dan Pencatatan Sipil Kabupaten Dompu menciptakan sebuah gerakan yang berfokus pada upaya untuk memberikan pemahaman dan sosialisasi pada semua tingkat pendidikan tentang pentingnya setiap anak memiliki administrasi kependudukan. Dukcapil Goes to School merupakan program inovasi yang bertujuan untuk memberikan edukasi dan kesadaran bagi siswa-siswi sekolah di semua tingkatan untuk memiliki kartu identitas diri. Identitas diri yang dimaksud adalah berupa KIA (Kartu Identitas Nak), KTP (Kartu Tanda Penduduk), dan Akta Kelahiran. Kartu Identitas Anak dapat dimiliki oleh anak berusia 0 – &lt;17 tahun sementara bagi siswa-siswi yang telah berusia 17 tahun keatas dapat memiliki KTP sebagai identitas diri. Selain memberikan edukasi, program inovasi ini dilanjtkan dengan melakukan perekaman dan pencetakan KTP-EL bagi siswa-siswi yang telah berusia 17 tahun.</p><p style=\"text-align: left;\">Di Sekolah Menengah Atas, kebanyakan siswa dan siswi merupakan remaja yang usianya berkisar antara 16 – 18 tahun. Bagi yang telah berusia 17 t ahun, akan direkam dan dicetak KTP-Elnya. Sedangkan, untuk siswa-siswi di Sekolah tingkat dasar dan pertama akan diberikan Kartu Identitas Anak bagi yang telah memiliki Akta Kelahiran.&nbsp;Program ini bertujuan untuk menuntaskan target kepemilikan KTP-EL untuk wajib KTP pemula serta mengedukasi siswa-siswi atas pentingnya dokumen administrasi kependudukan. Manfaat memiliki administrasi kependudukan berupa KTP-EL bagi siswa-siswi sangat banyak, misalnya sebagai syarat pengajuan beasiswam persiapan pendaftaran kerja atau kuliah, serta sebagai syarat kelengkapan untuk membuat Surat Izin Mengemudi (SIM).&nbsp;Khususnya menjelang pesta demokrasi, kepemilikan KTP-EL bagi siswa-siswi selaku pemilih pemula adalah hal yang sangat penting agar mereka dapat berpartisipasi dalam pemilihan umum yang akan dilaksanakan di waktu mendatang dan tidak kehilangan hak pilihnya sebagai warga negara.</p><p style=\"text-align: left;\">Selain itu, di dalam program Dukcapil Goes to School ini juga dilakukan pemutakhiran data kelahiran untuk para pelajar tersebut. Sehingga data kelahiran mereka akan terdata di database Dinas Dukcapil, mengingat masih banyak siswa-siswi yangbelum memiliki akta kelahiran. Tidak hanya itu, pemutakhiran data juga diperlukan bagi siswa-siswa yang di dalam dokumen kependudukannya terdapat kesalahan-kesalahan seperti perbedaan nama atau tanggal lahir antara dokumen kependudukan dengan ijazah yang telah mereka dapatkan sebelumnya.</p>', 'https://www.youtube.com/embed/EldHPPhn8eg', '7', '1', '2026-07-24 00:40:17', '2026-07-24 00:40:49');
INSERT INTO `innovations` (`id`, `title`, `slug`, `icon`, `color`, `description`, `content`, `youtube_url`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES ('26', '\"Ada Data\"', 'ada-data', '📋', '#4f46e5', 'Arsip Digital Data Dokumen Administrasi Kependudukan', '<p>Program Ada Data merupakan salahsatu program inovasi Dinas Kependudukan dan Pencatatan Sipil Kabupaten Dompu yang bertujuan untuk memberi kemudahan bagi masyarakat&nbsp; untuk mencari kembali arsip dokumen kependudukan yang pernah dijadikan bahan untuk kepengurusan dokumen adminsitrasi kependudukan sebelumnya. Ada Data merupakan program Arsip Digital Data Dokumen Admjinistrasi Kependudukan yang telah dilakukan sejak 2021 yang lalu.</p><p style=\"text-align: justify;\">Pengarsipan secara konvensional, yaitu dengan mengumpulkan dokumen-dokumen disatu tempat dan diberi nomor, kode, atau tanggal, memiliki banyak resiko seperti rusak erkena air, dimakan rayap, terbakar, hilang, atau usang dimakan usia. Sehingga, melakukan digitalisasi arsip menjadi hal yang sangat penting terutama di Dinas Kependudukan dan Pencatatan Sipil yang dimana setiap pengurusannya membutuhkan banyak lembar persyaratan untuk meninjau dokumen adminduk yang akan diterbitkan. Melalui digitalisasi, mencari berkas yang ingin dibutuhkan akan menjadi mudah dan tidak perlu khawatir dengan debu rayap, tikus, bahkan jika arsip terbawa banjir ataupun terbakar.</p><p style=\"text-align: justify;\">Semua berkas dokumen masyarakat yang telah diproses akan diatur sebagai arsip sesuai tanggal pengajuan. Setelah itu, semua berkas tersebut akan diatur dan dipindai (scan) ke dalam komputer terlebih dahulu oleh petugas lalu kemudian akan diinput ke dalam Sistem Administrasi Kependudukan (SIAK). Selain dinput ke dalam SIAK, semua berkas juga diarsipkan dibeberapa tempat seperti di drive komputer, di harddisk eksternal, flashdrive eksternal, dan terakhir adalah didalam arsip SIAK. Hal ini menjadi salah satu upaya Dinas Dukcapil Dompu untuk membuat Arsip Digital Dokumen Administrasi Kependudukan menjadi sarana digitalisasi dokumen sebagai respon terhadap perkembangan teknologi yang semakin meningkat pesat.</p><p style=\"text-align: justify;\">Diharapkan dengan adanya inovasi ini, arsiparis dokumen di Dinas Kependudukan dan Pencatatan Sipil akan menjadi semakin mudah, tidak ada lagi dokumen berserakan, serta akan mempermudah pengecekan kembali dokumen-dokumen yang telah diproses tanpa perlu membuang waktu untuk membongkar satu persatu dokumen hardfile yang telah dkerjakan karena kini dapat diakses dengan mudah melalui SIAK. Dapat dikatakan bahwa tujuan dari program ini adalah upaya penyelamatan informasi untuk dokumen yang diperlukan di masa yang akan datang.</p>', 'https://www.youtube.com/embed/8WbyRFE7QY8', '8', '1', '2026-07-24 00:45:03', '2026-07-24 00:47:29');
INSERT INTO `innovations` (`id`, `title`, `slug`, `icon`, `color`, `description`, `content`, `youtube_url`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES ('27', '\"Go To Lakei\"', 'go-to-lakei', '✨', '#4f46e5', 'Inovasi \"Go To Lakei\" - Pergi Pelayanan Keliling', '<p>Go To Lakei atau disebut juga Pergi Pelayanan Keliling merupakan salah satu inovasi Dinas Kependudukan dan Pencatatan Sipil Kabupaten Dompu dimana Tim Dukcapil Dompu melakukan pelayanan keliling berupa sosialisasi administrasi kependudukan di delapan kecamatan yang ada di Kabupaten Dompu. Program ini telah dilaksanakan semenjak tahun 2021 lalu dan di dalam pelayanan ini melibatkan empat bidang yang ada di Dinas Dukcapil Dompu, yaitu bidang pendaftaran penduduk (Dafduk), bidang pencatatan sipil (Capil), bidang pengelolaan informasi dan administrasi kependudukan (PIAK), serta bidang&nbsp; pemanfaatan data dan inovasi pelayanan (PDIP).</p><p style=\"text-align: justify;\">Adapun tujuan dari program ini adalah mendekatkan pelayanan kepada masyarakat melalui sosialisasi untuk mewujudkan Gerakan Indonesia Sadar Adminduk. Pada mekanismenya, sosialisasi ini dilakukan di tiap kecamatan dengan mengundang seluruh kepala desa dan kepala dusun yang ada di kecamatan tersebut. Mengingat bahwa para perangkat desa inilah nantinya yang merupakan perpanjangtanganan dari pelayanan Dinas Dukcapil kepada masyarakat. DI dalam program ini, Tim Dukcapil berkeliling untuk melakukan sosialisasi terkait kebijakan administrasi kependudukan, terutama kebijakan-kebijakan terbaru yang perlu diketahui oleh masyarakat, sehingga nantinya sebelum melakukan pengurusan ke Dinas Dukcapil, perangkat desa dapat memberitahukan kepada warganya terlebih dahulu terkait persyaratan-persyaratan serta kebijakan dalam mengurus administrasi kependudukan.</p><p style=\"text-align: justify;\">Adapun di dalam kegiatan sosialisasi tersebut, diberikan kesempatan untuk diskusi dan tanya jawab terkait administrasi kependudukan, terutama mengenai permasalahan-permasalahan yang sering dijumpai oleh masyarakat saat mengurus administrasi kependudukan, seperti data ganda, pengurusan kartu keluarga dengan kawin tidak tercatat, atau juga mengenai status anak luar kawin (Anak Ibu). Melalui program inovasi ini diharapkan agar hal-hal yang masih abu-abu bagi masyarakat dapat diperjelas sehingga tidak ada lagi kendala saat mengurus administrasi kependudukan.</p><p style=\"text-align: justify;\"></p><p style=\"text-align: justify;\">Selain itu, di dalam kegiatan ini juga diperkenalkan kontak-kontak pengaduan dan kanal resmi informasi mengenai Dinas Kependudukan dan Pencatatan Sipil Kabupaten Dompu seperti nomor pengaduan di Whatsapp, kanal media sosial Facebook, Instagram, serta website pelayanan dokumen adminduk dan juga website khusus untuk informasi administrasi kependudukan di Dinas Kependudukan dan Pencatatan Sipil Kabupaten Dompu.</p>', 'https://www.youtube.com/embed/1sFS7dkFRIM', '10', '1', '2026-07-27 17:02:09', '2026-07-27 17:02:18');
INSERT INTO `innovations` (`id`, `title`, `slug`, `icon`, `color`, `description`, `content`, `youtube_url`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES ('28', '\"Gadis Samakai\"', 'gadis-samakai', '🌟', '#4f46e5', 'Inovasi \"Gadis Samakai\" - Gerakan Anak Didik dan Siswa Sadar Memiliki Kartu Identitas', '<p>Inovasi “Gadis Samakai” atau&nbsp; Gerakan Anak Didik dan Siswa Sadar Memiliki Kartu Identitas adalah inovasi yang dilakukan dengan mendatangi Lembaga Pendidikan mulai dari TK, SD/MI, SMP/MTs, SMA/SMK/MAN dan Pesantren dengan memberikan Sosialisasi serta Pelayanan Mobile untuk Perekaman KTP-el, Penerbitan Akta Kelahiran, dan Penerbitan KIA semenjak Tahun 2019.</p>', NULL, '10', '1', '2026-07-27 17:03:26', '2026-07-27 17:03:37');
INSERT INTO `innovations` (`id`, `title`, `slug`, `icon`, `color`, `description`, `content`, `youtube_url`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES ('29', '\"Kado Biru\"', 'kado-biru', '❤️', '#4f46e5', 'Inovasi \"Kado Biru\" - Kepemilikan Dokumen Kependudukan Bagi Pengantin Baru', '<p>Kado Biru atau Kepemilikan Dokumen Kependudukan Bagi Pengantin Baru adalah salah satu inovasi Dinas Dukcapil Dompu yang bekerjasama dengan Pihak Kementerian Agama dan KUA Kabupaten Dompu untuk menerbitkan 5 (lima) dokumen kependudukan bagi Pengantin Baru yaitu Kartu Keluarga Orang Tua, Kartu Keluarga Mertua, Kartu Keluarga Pasangan SUami-Istri, dn 2 Pasang KTP untuk Pengantin Baru.</p>', NULL, '11', '1', '2026-07-27 17:04:22', '2026-07-27 17:04:32');
INSERT INTO `innovations` (`id`, `title`, `slug`, `icon`, `color`, `description`, `content`, `youtube_url`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES ('30', '\"SABATIK\"', 'sabatik', '💎', '#4f46e5', 'Inovasi \"SABATIK\" - Satu Bahan Dapat Tiga Dokumen', '<p>Satu Bahan Dapat Tiga Dokumen merupakan salah satu Inovasi Dinas Dukcapil Dompu dimana pelayanan terintegrasi dengan melengkapi satu berkas persyaratanan, maka pemohon bisa mendapatkan tiga dokumen kependudukan berupa Kartu Keluarga, Akta Kelahiran, dan Kartu Identitas Anak (KIA). Layanan ini juga disebut <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary-600 dark:text-primary-400 font-bold underline\" href=\"https://dukcapil.dompukab.go.id/?page_id=2718\">Pelayanan Dokumen 3 in 1 (Anak Baru Lahir</a>).</p>', NULL, '12', '1', '2026-07-27 17:05:09', '2026-07-27 17:05:09');

DROP TABLE IF EXISTS `job_batches`;
CREATE TABLE `job_batches` (
  `id` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `total_jobs` int NOT NULL,
  `pending_jobs` int NOT NULL,
  `failed_jobs` int NOT NULL,
  `failed_job_ids` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `options` mediumtext COLLATE utf8mb4_unicode_ci,
  `cancelled_at` int DEFAULT NULL,
  `created_at` int NOT NULL,
  `finished_at` int DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `jobs`;
CREATE TABLE `jobs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `queue` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `payload` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `attempts` smallint unsigned NOT NULL,
  `reserved_at` int unsigned DEFAULT NULL,
  `available_at` int unsigned NOT NULL,
  `created_at` int unsigned NOT NULL,
  PRIMARY KEY (`id`),
  KEY `jobs_queue_index` (`queue`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `kecamatans`;
CREATE TABLE `kecamatans` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `code` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ibukota` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Ibukota / pusat kecamatan',
  `area_km2` decimal(10,2) DEFAULT NULL COMMENT 'Luas wilayah km2',
  `population_total` int unsigned NOT NULL DEFAULT '0',
  `male_count` int unsigned NOT NULL DEFAULT '0',
  `female_count` int unsigned NOT NULL DEFAULT '0',
  `desa_count` smallint unsigned NOT NULL DEFAULT '0',
  `sort_order` smallint unsigned NOT NULL DEFAULT '0',
  `notes` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `kecamatans_code_unique` (`code`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

