INSERT INTO `news` (`id`, `user_id`, `news_category_id`, `title`, `slug`, `excerpt`, `content`, `thumbnail`, `status`, `is_featured`, `is_breaking`, `view_count`, `meta_title`, `meta_description`, `og_image`, `published_at`, `created_at`, `updated_at`, `deleted_at`) VALUES ('45', '1', '1', 'Penandatanganan Perjanjian Kerja Sama (PKS) Pemanfaatan Data dan Percepatan Pelayanan Dokumen Administrasi Kependudukan Bersama 15 OPD di Kabupaten Dompu', 'penandatanganan-perjanjian-kerja-sama-pks-pemanfaatan-data-dan-percepatan-pelayanan-dokumen-administrasi-kependudukan-bersama-15-opd-di-kabupaten-dompu', 'Posted on Juli 6, 2023 by adminduk		
			/*! elementor - v3.18.0 - 08-12-2023 */
.elementor-widget-image{text-align:center}.elementor-widget-image a{display:inline-block}.elementor-widget-image a img[src$=\".svg\"]{width:48px}.elementor-widget-image', 'Posted on <a title=\"6:09 am\" href=\"https://dukcapildompu.info/2023/07/06/penandatanganan-perjanjian-kerja-sama-pks-pemanfaatan-data-dan-percepatan-pelayanan-dokumen-administrasi-kependudukan-bersama-15-opd-di-kabupaten-dompu/\" rel=\"bookmark\"><time datetime=\"2023-07-06T06:09:34+00:00\">Juli 6, 2023</time></a> by <a title=\"View all posts by adminduk\" href=\"https://dukcapildompu.info/author/adminduk/\" rel=\"author\">adminduk</a>		
																														
		<p>Dinas Kependudukan dan Pencatatan Sipil Kabupaten Dompu pada Kamis, 06 Juli 2023 telah melaksanakan penandatanganan Perjanjian Kerja Sama  (PKS) Pemanfaatan Data dan Percepatan Pelayanan Dokumen Administrasi Kependudukan bersama 15 OPD selaku Lembaga pengguna di lingkungan Pemerintah Daerah Kabupaten Dompu. Adapun OPD yang melaksanakan PKS tersebut antara lain adalah Dinas Dikpora, Dinas Sosial, Dinas Pertanian dan Perkebunan, Dinas Kelautan dan Perikanan, Dinas P3A, Dinas PPKB, Dinas NAKERTRANS, Dinas Kominfo, DInas PMPD, Dinas Kesehatan, RSUD Kab. Dompu, RSU Manggelewa, Puskesmas Kota, Puskesmas Dompu Barat, dan Puskesmas Dompu Timur.</p><p>Kegiatan penandatangan Perjanjian Kerja Sama ini turut dihadiri oleh Sekretaris Daerah Kabupaten Dompu, Bapak Gatot Gunawan PP, SKM., M.Mkes., yang juga memberi sambutan serta arahan terkait Penandatanganan Perjanjian Kerja Sama ini. Penandatanganan PKS ini adalah salah satu tahapan dalam pemanfaatan data kependudukan yang nantinya dilanjutkan dengan pembahasan teknis dengan OPD yang telah melaksanakan penandatanganan Perjanjian Kerja Sama tersebut.</p><p>Pada kesempatan ini, Kepala Dinas Kependudukan dan Pencatatan Sipil Kabupaten Dompu, Drs. Abd. Najib., menyampaikan bahwa pemanfataan data ini mendorong semua perangkat daerah kearah kebijakan satu data Indonesia (one data policy) yang basis datanya berasal dari Dinas Dukcapil dengan tujuan agar tidak ada sumber data yang berbeda-beda.</p><p>Selain penandatanganan Kerja Sama, acara juga dilanjutkan dengan Penyerahan DP4 Pemilihan Kepala Desa Serentak di 33 Desa Kabupaten Dompu kepada  Dinas Pemberdayaan Masyarakat dan Pemerintah Desa Kabupaten Dompu yang diwakilkan oleh Sekretaris DPMPD Kab. Dompu, Bapak Rudi Purtomo, SP.</p><p>Setelah melakukan penandatangan oleh semua OPD dan penyerahan DP4 Pilkades Kab. Dompu, kegiatan ini kemudian ditutup dengan agenda pengaktivasian Identitas Kependudukan Digital atau IKD bagi beberapa Kepala OPD yang belum memiliki IKD.</p>', 'https://dukcapil.dompukab.go.id/wp-content/uploads/2023/12/1-upload-768x768-1.png', 'published', '0', '0', '0', 'Penandatanganan Perjanjian Kerja Sama (PKS) Pemanfaatan Data dan Percepatan Pelayanan Dokumen Administrasi Kependudukan Bersama 15 OPD di Kabupaten Dompu', 'Posted on Juli 6, 2023 by adminduk		
			/*! elementor - v3.18.0 - 08-12-2023 */
.elementor-widget-image{text-align:center}.elementor-widget-image a{display:inline-block}.elementor-widget-image a img[src$=\".svg\"]{width:48px}.elementor-widget-image', 'https://dukcapil.dompukab.go.id/wp-content/uploads/2023/12/1-upload-768x768-1.png', '2023-12-18 03:03:53', '2026-07-22 03:20:25', '2026-07-23 11:24:18', NULL);
INSERT INTO `news` (`id`, `user_id`, `news_category_id`, `title`, `slug`, `excerpt`, `content`, `thumbnail`, `status`, `is_featured`, `is_breaking`, `view_count`, `meta_title`, `meta_description`, `og_image`, `published_at`, `created_at`, `updated_at`, `deleted_at`) VALUES ('48', '1', '1', 'Pelayanan Mobile Perekaman KTP-EL Pemula dan Wajib KTP Di MAN Dompu', 'pelayanan-mobile-perekaman-ktp-el-pemula-dan-wajib-ktp-di-man-dompu', 'https://drive.google.com/file/d/1glEGLFITpjAwLAg3CRmtu_ExOu9yLu0v/view?usp=drive_linkHalo Teman Dompu... Pada hari Rabu 10 Januari 2024 Dinas Dukcapil melakukan perekaman KTP-EL di MAN 1 Dompu untuk siswa-siswi yang memasuki usia Pemula dan Wajib KT', 'https://drive.google.com/file/d/1glEGLFITpjAwLAg3CRmtu_ExOu9yLu0v/view?usp=drive_linkHalo Teman Dompu... Pada hari Rabu 10 Januari 2024 Dinas Dukcapil melakukan perekaman KTP-EL di MAN 1 Dompu untuk siswa-siswi yang memasuki usia Pemula dan Wajib KTP. Untuk teman Dompu yang sudah menginjak usia 17 atau masih 16 tahun, yuuk lakukan perekaman KTP-EL di Dinas Dukcapil Dompu. Cukup bawa Fotocopy Kartu Keluarga yang bersangkutan yaa... Yukk Tanamkan Gerakan Indonesia Sadar Adminduk dan segera miliki KTP-EL sebagai identitas yang Sah dan diakui negara ya. Ingat, KTP-EL bukanlah kebutuhan, tapi Kewajiban dan Hak semua Warga Negara Indonesia. Gisa Kalembo Ade. Dukcapil Prima, Indonesia Maju________<a tabindex=\"0\" role=\"link\" href=\"https://www.facebook.com/hashtag/adminduk?__eep__=6&amp;__cft__[0]=AZXO2zX_9DNRG6vtd_eDnWpMaL3Ci0XN1oiWrblg5oWlqBvuI8OBIG-6RW4QKNp0B58U0Pl-FSOSJKvhkSzy9T4I4LqWhpPw5CcoRImwKUOjwBEfptnYSQ69MJTo0sjWh1D_7BctqRwav9WpNAdBVGT-mSPygrSt2MHvXWUrMu8dMJHmJfhN8DORVQF0g9TMDA0&amp;__tn__=*NK-R\">#Adminduk</a><a tabindex=\"0\" role=\"link\" href=\"https://www.facebook.com/hashtag/dukcapildompu?__eep__=6&amp;__cft__[0]=AZXO2zX_9DNRG6vtd_eDnWpMaL3Ci0XN1oiWrblg5oWlqBvuI8OBIG-6RW4QKNp0B58U0Pl-FSOSJKvhkSzy9T4I4LqWhpPw5CcoRImwKUOjwBEfptnYSQ69MJTo0sjWh1D_7BctqRwav9WpNAdBVGT-mSPygrSt2MHvXWUrMu8dMJHmJfhN8DORVQF0g9TMDA0&amp;__tn__=*NK-R\">#DukcapilDompu</a><a tabindex=\"0\" role=\"link\" href=\"https://www.facebook.com/hashtag/kabupatendompu?__eep__=6&amp;__cft__[0]=AZXO2zX_9DNRG6vtd_eDnWpMaL3Ci0XN1oiWrblg5oWlqBvuI8OBIG-6RW4QKNp0B58U0Pl-FSOSJKvhkSzy9T4I4LqWhpPw5CcoRImwKUOjwBEfptnYSQ69MJTo0sjWh1D_7BctqRwav9WpNAdBVGT-mSPygrSt2MHvXWUrMu8dMJHmJfhN8DORVQF0g9TMDA0&amp;__tn__=*NK-R\">#KabupatenDompu</a><a tabindex=\"0\" role=\"link\" href=\"https://www.facebook.com/hashtag/ktp?__eep__=6&amp;__cft__[0]=AZXO2zX_9DNRG6vtd_eDnWpMaL3Ci0XN1oiWrblg5oWlqBvuI8OBIG-6RW4QKNp0B58U0Pl-FSOSJKvhkSzy9T4I4LqWhpPw5CcoRImwKUOjwBEfptnYSQ69MJTo0sjWh1D_7BctqRwav9WpNAdBVGT-mSPygrSt2MHvXWUrMu8dMJHmJfhN8DORVQF0g9TMDA0&amp;__tn__=*NK-R\">#KTP</a>-EL<a tabindex=\"0\" role=\"link\" href=\"https://www.facebook.com/hashtag/pelayananyangmembahagiakanmasyarakat?__eep__=6&amp;__cft__[0]=AZXO2zX_9DNRG6vtd_eDnWpMaL3Ci0XN1oiWrblg5oWlqBvuI8OBIG-6RW4QKNp0B58U0Pl-FSOSJKvhkSzy9T4I4LqWhpPw5CcoRImwKUOjwBEfptnYSQ69MJTo0sjWh1D_7BctqRwav9WpNAdBVGT-mSPygrSt2MHvXWUrMu8dMJHmJfhN8DORVQF0g9TMDA0&amp;__tn__=*NK-R\">#PelayananYangMembahagiakanMasyarakat</a>', NULL, 'published', '0', '0', '0', 'Pelayanan Mobile Perekaman KTP-EL Pemula dan Wajib KTP Di MAN Dompu', 'https://drive.google.com/file/d/1glEGLFITpjAwLAg3CRmtu_ExOu9yLu0v/view?usp=drive_linkHalo Teman Dompu... Pada hari Rabu 10 Januari 2024 Dinas Dukcapil melakukan perekaman KTP-EL di MAN 1 Dompu untuk siswa-siswi yang memasuki usia Pemula dan Wajib KT', NULL, '2024-01-11 07:41:28', '2026-07-22 03:20:26', '2026-07-23 11:24:18', NULL);
INSERT INTO `news` (`id`, `user_id`, `news_category_id`, `title`, `slug`, `excerpt`, `content`, `thumbnail`, `status`, `is_featured`, `is_breaking`, `view_count`, `meta_title`, `meta_description`, `og_image`, `published_at`, `created_at`, `updated_at`, `deleted_at`) VALUES ('49', '1', '1', 'Pelayanan Mobile Perekaman KTP-EL Pemula dan Wajib KTP serta Aktivasi IKD di SMKN 2 Dompu', 'pelayanan-mobile-perekaman-ktp-el-pemula-dan-wajib-ktp-serta-aktivasi-ikd-di-smkn-2-dompu', 'Teman Dompu  Hari ini, Kamis 11 Januari 2024 Dinas Dukcapil kembali melakukan perekaman KTP-EL untuk siswa-siswi yang memasuki usia pemula dan Wajib KTP di SMK', '<p>https://drive.google.com/file/d/1KY02_9ADneYBth08zUQ9Olz4TytM0wxd/view?usp=drive_link</p>
<p>Halo Teman Dompu <img src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/tf5/1/16/1f44b_1f3fb.png\" alt=\"??\" width=\"16\" height=\"16\"> Hari ini, Kamis 11 Januari 2024 Dinas Dukcapil kembali melakukan perekaman KTP-EL untuk siswa-siswi yang memasuki usia pemula dan Wajib KTP di SMKN 2 Dompu.&nbsp;Ikut serta juga Bapak dan Ibu Guru SMKN 2 Dompu yang dengan antusias melakukan Aktivasi Identitas Kependudukan Digital pada pagi hari ini.&nbsp;Yukk Tanamkan Gerakan Indonesia Sadar Adminduk dan segera miliki KTP-EL sebagai identitas yang Sah dan diakui negara ya.&nbsp;Ingat, KTP-EL bukanlah kebutuhan, tapi Kewajiban dan Hak semua Warga Negara Indonesia&nbsp;&nbsp;Gisa Kalembo Ade.Dukcapil Prima, Indonesia Maju ________<a href=\"https://www.facebook.com/hashtag/adminduk?__eep__=6&amp;__cft__[0]=AZUxgRcdyNwOUiRntBYmnektuUUYgks-8d-17Acdl3TOEj38AtBhBugXLNyzzUnU8thlRAZkblB0hoJU8sbdOwMAs4msvudFWKspSYIvmdu0GJdjtu_NGyO3EqB-bBn8bAciuJfDm6htFFb7cA5QYJxCqBey8HZHCnBOqgjujZwtir2NJRLhhktvL84IOYm2_mI&amp;__tn__=*NK-R\">#Adminduk</a><a href=\"https://www.facebook.com/hashtag/dukcapildompu?__eep__=6&amp;__cft__[0]=AZUxgRcdyNwOUiRntBYmnektuUUYgks-8d-17Acdl3TOEj38AtBhBugXLNyzzUnU8thlRAZkblB0hoJU8sbdOwMAs4msvudFWKspSYIvmdu0GJdjtu_NGyO3EqB-bBn8bAciuJfDm6htFFb7cA5QYJxCqBey8HZHCnBOqgjujZwtir2NJRLhhktvL84IOYm2_mI&amp;__tn__=*NK-R\">#DukcapilDompu</a><a href=\"https://www.facebook.com/hashtag/kabupatendompu?__eep__=6&amp;__cft__[0]=AZUxgRcdyNwOUiRntBYmnektuUUYgks-8d-17Acdl3TOEj38AtBhBugXLNyzzUnU8thlRAZkblB0hoJU8sbdOwMAs4msvudFWKspSYIvmdu0GJdjtu_NGyO3EqB-bBn8bAciuJfDm6htFFb7cA5QYJxCqBey8HZHCnBOqgjujZwtir2NJRLhhktvL84IOYm2_mI&amp;__tn__=*NK-R\">#KabupatenDompu</a><a href=\"https://www.facebook.com/hashtag/ktp?__eep__=6&amp;__cft__[0]=AZUxgRcdyNwOUiRntBYmnektuUUYgks-8d-17Acdl3TOEj38AtBhBugXLNyzzUnU8thlRAZkblB0hoJU8sbdOwMAs4msvudFWKspSYIvmdu0GJdjtu_NGyO3EqB-bBn8bAciuJfDm6htFFb7cA5QYJxCqBey8HZHCnBOqgjujZwtir2NJRLhhktvL84IOYm2_mI&amp;__tn__=*NK-R\">#KTP</a>-EL<a href=\"https://www.facebook.com/hashtag/pelayananyangmembahagiakanmasyarakat?__eep__=6&amp;__cft__[0]=AZUxgRcdyNwOUiRntBYmnektuUUYgks-8d-17Acdl3TOEj38AtBhBugXLNyzzUnU8thlRAZkblB0hoJU8sbdOwMAs4msvudFWKspSYIvmdu0GJdjtu_NGyO3EqB-bBn8bAciuJfDm6htFFb7cA5QYJxCqBey8HZHCnBOqgjujZwtir2NJRLhhktvL84IOYm2_mI&amp;__tn__=*NK-R\">#PelayananYangMembahagiakanMasyarakat</a><a href=\"https://www.facebook.com/hashtag/dukcapilgodigital?__eep__=6&amp;__cft__[0]=AZUxgRcdyNwOUiRntBYmnektuUUYgks-8d-17Acdl3TOEj38AtBhBugXLNyzzUnU8thlRAZkblB0hoJU8sbdOwMAs4msvudFWKspSYIvmdu0GJdjtu_NGyO3EqB-bBn8bAciuJfDm6htFFb7cA5QYJxCqBey8HZHCnBOqgjujZwtir2NJRLhhktvL84IOYm2_mI&amp;__tn__=*NK-R\">#DukcapilGoDigital</a><a href=\"https://www.facebook.com/hashtag/identitaskependudukandigital?__eep__=6&amp;__cft__[0]=AZUxgRcdyNwOUiRntBYmnektuUUYgks-8d-17Acdl3TOEj38AtBhBugXLNyzzUnU8thlRAZkblB0hoJU8sbdOwMAs4msvudFWKspSYIvmdu0GJdjtu_NGyO3EqB-bBn8bAciuJfDm6htFFb7cA5QYJxCqBey8HZHCnBOqgjujZwtir2NJRLhhktvL84IOYm2_mI&amp;__tn__=*NK-R\">#IdentitasKependudukanDigita</a></p>', NULL, 'published', '0', '0', '6', 'Pelayanan Mobile Perekaman KTP-EL Pemula dan Wajib KTP serta Aktivasi IKD di SMKN 2 Dompu', 'https://drive.google.com/file/d/1KY02_9ADneYBth08zUQ9Olz4TytM0wxd/view?usp=drive_linkHalo Teman Dompu  Hari ini, Kamis 11 Januari 2024 Dinas Dukcapil kembali melakukan perekaman KTP-EL untuk siswa-siswi yang memasuki usia pemula dan Wajib KTP di SMK', '/storage/migration-media/fedd552f-f653-4287-8086-a780351d9f7d/1f44b-1f3fb.png', '2024-01-11 07:43:00', '2026-07-22 03:20:26', '2026-07-23 11:24:18', NULL);
INSERT INTO `news` (`id`, `user_id`, `news_category_id`, `title`, `slug`, `excerpt`, `content`, `thumbnail`, `status`, `is_featured`, `is_breaking`, `view_count`, `meta_title`, `meta_description`, `og_image`, `published_at`, `created_at`, `updated_at`, `deleted_at`) VALUES ('51', '1', '1', 'Dukcapil Dompu Laksanakan Pelayanan Mobile di Desa Nangakara, DPMPD Dompu Lakukan Pemantauan', 'dukcapil-dompu-laksanakan-pelayanan-mobile-di-desa-nangakara-dpmpd-dompu-lakukan-pemantauan', 'hari Kamis, 06 Juni 2024 Dinas Kependudukan dan Pencatatan Sipil Kabupaten Dompu melakukan Pelayanan Jemput Bola Layanan Gisa di Desa Nangakara, Kecamatan Pekat. Kegiatan pelayanan yang dilaksanak', '<figure class=\"media\"><oembed url=\"https://www.youtube.com/watch?v=Z8-6vLFzAQg\"></oembed></figure><p>hari Kamis, 06 Juni 2024 Dinas Kependudukan dan Pencatatan Sipil Kabupaten Dompu melakukan Pelayanan Jemput Bola Layanan Gisa di Desa Nangakara, Kecamatan Pekat.&nbsp;Kegiatan pelayanan yang dilaksanakan di Desa Nangakara ini merupakan kolaborasi dengan Dinas Pemberdayaan Masyarakat dan Pemerintahan Desa Kabupaten Dompu yang juga melakukan pemantauan dan pengawasan terhadap penertiban adminduk di Desa Nangakara.&nbsp;Pelayanan adminduk yang dilakukan seperti perekaman dan pencetakan ktp, pembuatan Kartu Keluarga dan Akta Kelahiran, juga pelayanan adminduk lain seperti KIA, Akta Kematian, dan juga Akta Perkawinan.&nbsp;Di setiap pelayanan mobile adminduk yang dilakukan oleh Dinas Dukcapil Dompu di desa, Dukcapil juga selalu melakukan layanan perekaman dan pencetakan KTP bagi penduduk rentan seperti Lansia, Difabel, maupun ODGJ yang terdapat di desa tersebut.&nbsp;Tidak lupa juga Dinas Dukcapil Dompu mensosialisasikan dan menerima layanan aktivasi Identitas Kependudukan Digital bagi para penduduk di desa.&nbsp;Turut hadir Ibu Camat Pekat, Ibu Nuraini, S.Pd yang mengapresiasi pelayanan jemput bola telah dilakukan oleh Dinas Dukcapil Dompu dan membawa manfaat dalam peningkatakankepemilikan adminduk bagi masyarakat di Kecamatan Pekat, khususnya kali ini di Desa Nangakara.&nbsp;Sambutan baik juga disampaikan oleh Bapak Iryanto selaku Kepala Desa Nangakara, mengingat masih banyaknya masyarakat yang belum mengurus dokumen adminduknya karena jarak Desa yang cukup jauh dari pusat Kabupaten Dompu dimana kantor Dinas Dukcapil Dompu terletak.&nbsp;&nbsp;&nbsp;</p>', 'news/2026/07/b0550cb1-1c3e-49f5-96c5-f7c77d426150.webp', 'published', '0', '0', '0', 'Dukcapil Dompu Laksanakan Pelayanan Mobile di Desa Nangakara, DPMPD Dompu Lakukan Pemantauan', 'https://youtu.be/Z8-6vLFzAQg?si=rU0a55yIjikgIjGePada hari Kamis, 06 Juni 2024 Dinas Kependudukan dan Pencatatan Sipil Kabupaten Dompu melakukan Pelayanan Jemput Bola Layanan Gisa di Desa Nangakara, Kecamatan Pekat. Kegiatan pelayanan yang dilaksanak', NULL, '2024-06-09 16:26:00', '2026-07-22 03:20:27', '2026-07-23 11:24:18', NULL);
INSERT INTO `news` (`id`, `user_id`, `news_category_id`, `title`, `slug`, `excerpt`, `content`, `thumbnail`, `status`, `is_featured`, `is_breaking`, `view_count`, `meta_title`, `meta_description`, `og_image`, `published_at`, `created_at`, `updated_at`, `deleted_at`) VALUES ('54', '1', '2', 'Sosialisasi Penataan Pendaftaran Penduduk dan Layanan Administrasi Kependudukan Berbasis Penugasan Desa Kabupaten Dompu Tahun 2025', 'sosialisasi-penataan-pendaftaran-penduduk-dan-layanan-administrasi-kependudukan-berbasis-penugasan-desa-kabupaten-dompu-tahun-2025', 'Kamis, 13 Maret 2025 Dinas Kependudukan dan Pencatatan Sipil Kabupaten Dompu telah melaksanakan Sosialisasi Penataan Pendaftaran Penduduk dan Layanan Administrasi Kependudukan Berbasis Penugasan Desa. Kegiatan sosialisasi yang dihadiri dan dibuka ole', '<p>Kamis, 13 Maret 2025 Dinas Kependudukan dan Pencatatan Sipil Kabupaten Dompu telah melaksanakan Sosialisasi Penataan Pendaftaran Penduduk dan Layanan Administrasi Kependudukan Berbasis Penugasan Desa. Kegiatan sosialisasi yang dihadiri dan dibuka oleh Bapak Wakil Bupati Kabupaten Dompu, Bapak Syirajuddin, SH ini bertujuan untuk menyamakan persepsi antara pemerintah daerah dengan pemerintah desa serta Dinas Dukcapil selaku instansi pelaksana tugas pelayanan administrasi kependudukan dalam hal layanan administrasi kependudukan berbasis penugasan desa.</p><p>Untuk mendukung program kerja Bupati dan Wakil Bupati Dompu Tahun 2025 ini, Dinas Dukcapil Kabupaten Dompu melakukan pendekatan yang dapat dilakukan untuk untuk memangkas waktu, biaya, dan kesulitan lainnya bagi masyarakat yang ingin mengurus adminduk, yaitu melalui layanan administrasi kependudukan yang dapat difasilitasi di tingkat desa dengan berbasis penugasan. Dalam sambutannya, Bapak Wakil Bupati Dompu, Bapak Syirajuddin, SH menyampaikan bahwa program layanan administrasi kependudukan berbasis penugasan di desa ini merupakan pendekatan layanan administrasi kependudukan kepada masyarakat yang dapat dilakukan langsung melalui desa sehingga masyarakat akan menjadi lebih mudah dan dekat dalam mengurus data kependudukannya. Sosialisasi yang diikuti oleh seluruh Kepala Desa dan Camat se-Kabupaten Dompu ini diharapkan dapat meningkatkan kepemilikan dokumen masyarakat sehingga setiap warga negara memiliki akses yang lebih mudah dan cepat terhadap dokumen-dokumen kependudukan yang menjadi haknya.</p>', 'news/2026/07/6c8a3a5b-1610-419b-8a07-10202cc78456.webp', 'published', '0', '0', '3', 'Sosialisasi Penataan Pendaftaran Penduduk dan Layanan Administrasi Kependudukan Berbasis Penugasan Desa Kabupaten Dompu Tahun 2025', 'Kamis, 13 Maret 2025 Dinas Kependudukan dan Pencatatan Sipil Kabupaten Dompu telah melaksanakan Sosialisasi Penataan Pendaftaran Penduduk dan Layanan Administrasi Kependudukan Berbasis Penugasan Desa. Kegiatan sosialisasi yang dihadiri dan dibuka ole', 'https://dukcapil.dompukab.go.id/wp-content/uploads/2025/03/1-300x300.png', '2025-03-19 01:19:00', '2026-07-22 03:20:28', '2026-07-26 17:12:37', NULL);
INSERT INTO `news` (`id`, `user_id`, `news_category_id`, `title`, `slug`, `excerpt`, `content`, `thumbnail`, `status`, `is_featured`, `is_breaking`, `view_count`, `meta_title`, `meta_description`, `og_image`, `published_at`, `created_at`, `updated_at`, `deleted_at`) VALUES ('55', '1', '2', 'Jadwal Perekaman KTP-el Keliling Masuk Desa Tahun 2026', 'perekaman-ktp-el-keliling-desa', 'Dukcapil Dompu menyelenggarakan layanan jemput bola perekaman KTP-el keliling ke seluruh desa.', '<p>Guna mempercepat cakupan kepemilikan KTP elektronik, Disdukcapil Kabupaten Dompu merilis jadwal perekaman keliling...</p>', NULL, 'published', '1', '0', '124', NULL, NULL, NULL, '2026-07-23 12:06:48', '2026-07-23 12:06:48', '2026-07-23 12:06:48', NULL);

DROP TABLE IF EXISTS `news_categories`;
CREATE TABLE `news_categories` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `color` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '#3b82f6',
  `sort_order` int NOT NULL DEFAULT '0',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `news_categories_slug_unique` (`slug`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `news_categories` (`id`, `name`, `slug`, `color`, `sort_order`, `created_at`, `updated_at`) VALUES ('1', 'Uncategorized', 'uncategorized', '#3b82f6', '0', '2026-07-21 04:22:21', '2026-07-21 04:22:21');
INSERT INTO `news_categories` (`id`, `name`, `slug`, `color`, `sort_order`, `created_at`, `updated_at`) VALUES ('2', 'Info Kependudukan', 'info-kependudukan', '#10b981', '1', '2026-07-23 12:06:48', '2026-07-23 12:06:48');

DROP TABLE IF EXISTS `news_news_tags`;
CREATE TABLE `news_news_tags` (
  `news_id` bigint unsigned NOT NULL,
  `news_tag_id` bigint unsigned NOT NULL,
  PRIMARY KEY (`news_id`,`news_tag_id`),
  KEY `news_news_tags_news_tag_id_foreign` (`news_tag_id`),
  CONSTRAINT `news_news_tags_news_id_foreign` FOREIGN KEY (`news_id`) REFERENCES `news` (`id`) ON DELETE CASCADE,
  CONSTRAINT `news_news_tags_news_tag_id_foreign` FOREIGN KEY (`news_tag_id`) REFERENCES `news_tags` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `news_tags`;
CREATE TABLE `news_tags` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `news_tags_slug_unique` (`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `notifications`;
CREATE TABLE `notifications` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `type` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `notifiable_type` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `notifiable_id` bigint unsigned NOT NULL,
  `data` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `read_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `notifications_notifiable_type_notifiable_id_index` (`notifiable_type`,`notifiable_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `official_achievements`;
