  `description` text COLLATE utf8mb4_unicode_ci,
  `document_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `official_achievements_official_id_foreign` (`official_id`),
  CONSTRAINT `official_achievements_official_id_foreign` FOREIGN KEY (`official_id`) REFERENCES `officials` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `official_achievements` (`id`, `official_id`, `title`, `issuer`, `year`, `description`, `document_url`, `sort_order`, `created_at`, `updated_at`) VALUES ('1', '1', 'Penghargaan Pelayanan Publik Kategori A- (Sangat Baik)', 'Kementerian PAN-RB', '2023', 'Penghargaan atas komitmen efisiensi dan transparansi pelayanan adminduk.', NULL, '0', '2026-07-23 12:21:03', '2026-07-23 12:21:03');

DROP TABLE IF EXISTS `official_documents`;
