DROP TABLE IF EXISTS `organization_layouts`;
CREATE TABLE `organization_layouts` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `layout_type` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'classic',
  `is_default` tinyint(1) NOT NULL DEFAULT '0',
  `config` json DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `organization_nodes`;
CREATE TABLE `organization_nodes` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `position_id` bigint unsigned DEFAULT NULL,
  `official_id` bigint unsigned DEFAULT NULL,
  `parent_id` bigint unsigned DEFAULT NULL,
  `node_title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `color_code` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '#2563eb',
  `icon` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'UserCheck',
  `sort_order` int NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `start_date` date DEFAULT NULL,
  `end_date` date DEFAULT NULL,
  `layout_coords` json DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `organization_nodes_position_id_foreign` (`position_id`),
  KEY `organization_nodes_official_id_foreign` (`official_id`),
  KEY `organization_nodes_parent_id_foreign` (`parent_id`),
  CONSTRAINT `organization_nodes_official_id_foreign` FOREIGN KEY (`official_id`) REFERENCES `officials` (`id`) ON DELETE SET NULL,
  CONSTRAINT `organization_nodes_parent_id_foreign` FOREIGN KEY (`parent_id`) REFERENCES `organization_nodes` (`id`) ON DELETE CASCADE,
  CONSTRAINT `organization_nodes_position_id_foreign` FOREIGN KEY (`position_id`) REFERENCES `organization_positions` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

