INSERT INTO `pages` (`id`, `user_id`, `title`, `slug`, `content`, `template`, `status`, `meta_title`, `meta_description`, `og_image`, `show_in_menu`, `sort_order`, `published_at`, `created_at`, `updated_at`, `deleted_at`) VALUES ('99', '1', 'Pelayanan Penerbitan Kartu Identitas Anak (KIA)', 'pelayanan-penerbitan-kartu-identitas-anak-kia-1', '<h2>Pelayanan Penerbitan Kartu Identitas Anak (KIA)</h2>		
					
					
															<svg viewBox=\"0 0 192 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M0 384.662V127.338c0-17.818 21.543-26.741 34.142-14.142l128.662 128.662c7.81 7.81 7.81 20.474 0 28.284L34.142 398.804C21.543 411.404 0 402.48 0 384.662z\"></path></svg>
