INSERT INTO `pages` (`id`, `user_id`, `title`, `slug`, `content`, `template`, `status`, `meta_title`, `meta_description`, `og_image`, `show_in_menu`, `sort_order`, `published_at`, `created_at`, `updated_at`, `deleted_at`) VALUES ('149', '1', 'Jenis Layanan', 'jenis-layanan-2', '<h2>Jenis Layanan</h2>		
			<link rel=\"stylesheet\" href=\"https://dukcapil.dompukab.go.id/wp-content/plugins/elementor/assets/css/widget-icon-list.min.css\">		<ul>
