INSERT INTO `pages` (`id`, `user_id`, `title`, `slug`, `content`, `template`, `status`, `meta_title`, `meta_description`, `og_image`, `show_in_menu`, `sort_order`, `published_at`, `created_at`, `updated_at`, `deleted_at`) VALUES ('189', '1', 'Inovasi \"Rinduku Berkobar\"', 'inovasi-rinduku-berkobar-pelayanan-restorasi-dokumen-kependudukan-bagi-warga-korban-bencana-banjir-tanah-longsor-dan-kebakaran-2', '<h2>Inovasi \"Rinduku Berkobar\" - Pelayanan Restorasi Dokumen Kependudukan Bagi Warga Korban Bencana (Banjir, Tanah Longsor, dan Kebakaran)</h2>		
		<p>Rinduku Berkobar adalah salah satu inovasi Dinas Dukcapil Dompu yaitu Pelayanan Restorasi Dokumen Kependudukan Bagi Warga Korban Bencana (Banjir, Tanah Longsor, dan Kebakaran) dengan memberikan pelayanan langsung pada masyarakat yang kehilangan atau rusak dokumen kependudukan akibat bencana banjir, tanah longsor, maupun kebakaran sejak tahun 2020.</p>', 'default', 'published', 'Inovasi \"Rinduku Berkobar\"', '/*! elementor - v3.20.0 - 13-03-2024 */
