INSERT INTO `pages` (`id`, `user_id`, `title`, `slug`, `content`, `template`, `status`, `meta_title`, `meta_description`, `og_image`, `show_in_menu`, `sort_order`, `published_at`, `created_at`, `updated_at`, `deleted_at`) VALUES ('190', '1', 'Inovasi \"Gadis Samakai\"', 'inovasi-gadis-samakai-gerakan-anak-didik-dan-siswa-sadar-memiliki-kartu-identitas-2', '<h2>Inovasi \"Gadis Samakai\" - Gerakan Anak Didik dan Siswa Sadar Memiliki Kartu Identitas</h2>		
		<p>Inovasi \"Gadis Samakai\" atau  Gerakan Anak Didik dan Siswa Sadar Memiliki Kartu Identitas adalah inovasi yang dilakukan dengan mendatangi Lembaga Pendidikan mulai dari TK, SD/MI, SMP/MTs, SMA/SMK/MAN dan Pesantren dengan memberikan Sosialisasi serta Pelayanan Mobile untuk Perekaman KTP-el, Penerbitan Akta Kelahiran, dan Penerbitan KIA semenjak Tahun 2019.</p>', 'default', 'published', 'Inovasi \"Gadis Samakai\"', '/*! elementor - v3.20.0 - 13-03-2024 */
.elementor-column .elementor-spacer-inner{height:var(--spacer-size)}.e-con{--container-widget-width:100%}.e-con-inner>.elementor-widget-spacer,.e-con>.elementor-widget-spacer{width:var(--container-widget-width,', 'https://dukcapil.dompukab.go.id/wp-content/uploads/2024/02/Yellow-Illustrative-Brainstorming-Presentation-2.png', '0', '0', '2024-03-19 06:49:27', '2026-07-21 09:48:52', '2026-07-21 09:50:22', NULL);
INSERT INTO `pages` (`id`, `user_id`, `title`, `slug`, `content`, `template`, `status`, `meta_title`, `meta_description`, `og_image`, `show_in_menu`, `sort_order`, `published_at`, `created_at`, `updated_at`, `deleted_at`) VALUES ('191', '1', 'Inovasi \"Kado Biru\"', 'inovasi-kado-biru-kepemilikan-dokumen-kependudukan-bagi-pengantin-baru-2', '<h2>Inovasi \"Kado Biru\" - Kepemilikan Dokumen Kependudukan Bagi Pengantin Baru</h2>		
		<p>Kado Biru atau Kepemilikan Dokumen Kependudukan Bagi Pengantin Baru adalah salah satu inovasi Dinas Dukcapil Dompu yang bekerjasama dengan Pihak Kementerian Agama dan KUA Kabupaten Dompu untuk menerbitkan 5 (lima) dokumen kependudukan bagi Pengantin Baru yaitu Kartu Keluarga Orang Tua, Kartu Keluarga Mertua, Kartu Keluarga Pasangan SUami-Istri, dn 2 Pasang KTP untuk Pengantin Baru.</p>', 'default', 'published', 'Inovasi \"Kado Biru\"', '/*! elementor - v3.20.0 - 13-03-2024 */
.elementor-column .elementor-spacer-inner{height:var(--spacer-size)}.e-con{--container-widget-width:100%}.e-con-inner>.elementor-widget-spacer,.e-con>.elementor-widget-spacer{width:var(--container-widget-width,', 'https://dukcapil.dompukab.go.id/wp-content/uploads/2024/02/Blue-Creative-Employee-Training-Presentation-2.png', '0', '0', '2024-03-19 07:05:05', '2026-07-21 09:48:52', '2026-07-21 09:50:22', NULL);
