INSERT INTO `pages` (`id`, `user_id`, `title`, `slug`, `content`, `template`, `status`, `meta_title`, `meta_description`, `og_image`, `show_in_menu`, `sort_order`, `published_at`, `created_at`, `updated_at`, `deleted_at`) VALUES ('323', '1', 'Standar Pelayanan Publik', 'standar-pelayanan-publik', '<h2>Jenis Pelayanan</h2><p>Dukcapil Kabupaten Dompu melayani perekaman KTP-el, pembuatan Kartu Identitas Anak (KIA), Kartu Keluarga (KK), Akta Kelahiran, Akta Kematian, dan Surat Pindah.</p>', 'default', 'published', NULL, NULL, NULL, '1', '1', '2026-07-23 12:06:48', '2026-07-23 12:06:48', '2026-07-23 12:06:48', NULL);

