INSERT INTO `ppid_documents` (`id`, `category`, `subcategory`, `title`, `description`, `file_path`, `file_url`, `file_type`, `file_size`, `year`, `download_count`, `sort_order`, `is_published`, `created_by`, `created_at`, `updated_at`) VALUES ('28', 'sk_ppid', 'SK Standard Operating Procedure (SOP) PPID', 'SK Standard Operating Procedure (SOP) PPID', 'SK Standard Operating Procedure (SOP) PPID', 'ppid-documents/ELDtuDneZ6P45UX2hO9QV8uKBYTLEmKumwDRIi8F.pdf', NULL, 'pdf', '418161', '2026', '0', '0', '1', '1', '2026-07-27 16:40:09', '2026-07-27 16:40:09');

DROP TABLE IF EXISTS `ppid_pages`;
CREATE TABLE `ppid_pages` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `slug` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `icon` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `content` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `meta_title` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `meta_description` text COLLATE utf8mb4_unicode_ci,
  `sort_order` int NOT NULL DEFAULT '0',
  `is_published` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ppid_pages_slug_unique` (`slug`)
) ENGINE=InnoDB AUTO_INCREMENT=28 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `ppid_pages` (`id`, `slug`, `title`, `icon`, `content`, `meta_title`, `meta_description`, `sort_order`, `is_published`, `created_at`, `updated_at`) VALUES ('1', 'pengertian', 'Pengertian PPID', 'BookOpen', '<div class=\"space-y-10\">

  <!-- Overview Card -->
  <div class=\"p-6 sm:p-8 bg-gradient-to-br from-blue-900 via-indigo-900 to-slate-900 text-white rounded-3xl shadow-xl relative overflow-hidden\">
    <div class=\"absolute -right-10 -bottom-10 w-64 h-64 bg-blue-500/10 rounded-full blur-2xl\"></div>
    <div class=\"relative z-10 space-y-3 max-w-3xl\">
      <span class=\"px-3 py-1 bg-amber-500/20 text-amber-300 border border-amber-500/30 text-xs font-black uppercase rounded-lg tracking-wider\">
        Keterbukaan Informasi Publik
      </span>
      <h3 class=\"text-xl sm:text-2xl font-black tracking-tight\">Apa itu PPID?</h3>
      <p class=\"text-xs sm:text-sm text-blue-100/90 leading-relaxed font-medium\">
        <strong>Pejabat Pengelola Informasi dan Dokumentasi (PPID)</strong> adalah pejabat yang bertanggung jawab di bidang penyimpanan, pendokumentasian, penyediaan, dan/atau pelayanan informasi di badan publik. PPID dibentuk sebagai bentuk komitmen transparansi berdasarkan <strong>Undang-Undang Nomor 14 Tahun 2008</strong> tentang Keterbukaan Informasi Publik (KIP).
      </p>
    </div>
  </div>

  <!-- Dasar Hukum -->
  <div class=\"space-y-4\">
    <div class=\"flex items-center gap-2 border-b border-gray-100 dark:border-zinc-800 pb-3\">
      <span class=\"text-lg\">⚖️</span>
      <h3 class=\"text-lg font-black text-gray-900 dark:text-zinc-50 tracking-tight\">Dasar Hukum Pembentukan</h3>
    </div>

    <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">
      <div class=\"p-5 bg-white dark:bg-zinc-800/50 border border-gray-100 dark:border-zinc-700/60 rounded-2xl flex items-start gap-3.5 shadow-xs\">
        <div style=\"background-color: #eff6ff; color: #2563eb; border-color: #bfdbfe;\" class=\"w-10 h-10 rounded-xl flex items-center justify-center font-bold text-lg shrink-0 border\">
          📜
        </div>
        <div>
          <h4 class=\"text-xs font-extrabold text-gray-900 dark:text-zinc-100\">UU No. 14 Tahun 2008</h4>
          <p class=\"text-[11px] text-gray-500 dark:text-zinc-400 mt-1 leading-relaxed\">
            Undang-Undang Republik Indonesia tentang Keterbukaan Informasi Publik.
          </p>
        </div>
      </div>

      <div class=\"p-5 bg-white dark:bg-zinc-800/50 border border-gray-100 dark:border-zinc-700/60 rounded-2xl flex items-start gap-3.5 shadow-xs\">
        <div style=\"background-color: #eef2ff; color: #4f46e5; border-color: #c7d2fe;\" class=\"w-10 h-10 rounded-xl flex items-center justify-center font-bold text-lg shrink-0 border\">
          🏛️
        </div>
        <div>
          <h4 class=\"text-xs font-extrabold text-gray-900 dark:text-zinc-100\">PP No. 61 Tahun 2010</h4>
          <p class=\"text-[11px] text-gray-500 dark:text-zinc-400 mt-1 leading-relaxed\">
            Peraturan Pemerintah tentang Pelaksanaan UU No. 14 Tahun 2008.
          </p>
        </div>
      </div>

      <div class=\"p-5 bg-white dark:bg-zinc-800/50 border border-gray-100 dark:border-zinc-700/60 rounded-2xl flex items-start gap-3.5 shadow-xs\">
        <div style=\"background-color: #faf5ff; color: #9333ea; border-color: #e9d5ff;\" class=\"w-10 h-10 rounded-xl flex items-center justify-center font-bold text-lg shrink-0 border\">
          🏢
        </div>
        <div>
          <h4 class=\"text-xs font-extrabold text-gray-900 dark:text-zinc-100\">Permendagri No. 35 Tahun 2010</h4>
          <p class=\"text-[11px] text-gray-500 dark:text-zinc-400 mt-1 leading-relaxed\">
            Pedoman Pengelolaan Pelayanan Informasi &amp; Dokumentasi di Lingkungan Kemendagri &amp; Pemda.
          </p>
        </div>
      </div>

      <div class=\"p-5 bg-white dark:bg-zinc-800/50 border border-gray-100 dark:border-zinc-700/60 rounded-2xl flex items-start gap-3.5 shadow-xs\">
        <div style=\"background-color: #ecfdf5; color: #059669; border-color: #a7f3d0;\" class=\"w-10 h-10 rounded-xl flex items-center justify-center font-bold text-lg shrink-0 border\">
          📑
        </div>
        <div>
          <h4 class=\"text-xs font-extrabold text-gray-900 dark:text-zinc-100\">Peraturan Bupati Dompu</h4>
          <p class=\"text-[11px] text-gray-500 dark:text-zinc-400 mt-1 leading-relaxed\">
            Peraturan Bupati Dompu tentang Pengelolaan Pelayanan Informasi Publik Daerah.
          </p>
        </div>
      </div>
    </div>
  </div>

  <!-- Tujuan Keterbukaan Informasi -->
  <div class=\"space-y-4\">
    <div class=\"flex items-center gap-2 border-b border-gray-100 dark:border-zinc-800 pb-3\">
      <span class=\"text-lg\">🎯</span>
      <h3 class=\"text-lg font-black text-gray-900 dark:text-zinc-50 tracking-tight\">Tujuan Keterbukaan Informasi Publik</h3>
    </div>

    <div class=\"grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-4\">
      <div class=\"p-4 bg-slate-50/70 dark:bg-zinc-800/40 border border-gray-100 dark:border-zinc-800 rounded-2xl space-y-2\">
        <span style=\"color: #10b981;\" class=\"font-black text-base\">✓ 01</span>
        <p class=\"text-xs text-gray-700 dark:text-zinc-200 font-semibold leading-relaxed\">
          Menjamin hak warga negara untuk mengetahui rencana pembuatan kebijakan publik.
        </p>
      </div>

      <div class=\"p-4 bg-slate-50/70 dark:bg-zinc-800/40 border border-gray-100 dark:border-zinc-800 rounded-2xl space-y-2\">
        <span style=\"color: #10b981;\" class=\"font-black text-base\">✓ 02</span>
        <p class=\"text-xs text-gray-700 dark:text-zinc-200 font-semibold leading-relaxed\">
          Mendorong partisipasi aktif masyarakat dalam proses pengambilan kebijakan publik.
        </p>
      </div>

      <div class=\"p-4 bg-slate-50/70 dark:bg-zinc-800/40 border border-gray-100 dark:border-zinc-800 rounded-2xl space-y-2\">
        <span style=\"color: #10b981;\" class=\"font-black text-base\">✓ 03</span>
        <p class=\"text-xs text-gray-700 dark:text-zinc-200 font-semibold leading-relaxed\">
          Meningkatkan peran aktif masyarakat dalam pengelolaan tata pemerintahan.
        </p>
      </div>

      <div class=\"p-4 bg-slate-50/70 dark:bg-zinc-800/40 border border-gray-100 dark:border-zinc-800 rounded-2xl space-y-2\">
        <span style=\"color: #10b981;\" class=\"font-black text-base\">✓ 04</span>
        <p class=\"text-xs text-gray-700 dark:text-zinc-200 font-semibold leading-relaxed\">
          Mewujudkan penyelenggaraan tata kelola pemerintahan yang baik (Good Governance).
        </p>
      </div>

      <div class=\"p-4 bg-slate-50/70 dark:bg-zinc-800/40 border border-gray-100 dark:border-zinc-800 rounded-2xl space-y-2\">
        <span style=\"color: #10b981;\" class=\"font-black text-base\">✓ 05</span>
        <p class=\"text-xs text-gray-700 dark:text-zinc-200 font-semibold leading-relaxed\">
          Mengetahui alasan kebijakan publik yang mempengaruhi hajat hidup orang banyak.
        </p>
      </div>

      <div class=\"p-4 bg-slate-50/70 dark:bg-zinc-800/40 border border-gray-100 dark:border-zinc-800 rounded-2xl space-y-2\">
        <span style=\"color: #10b981;\" class=\"font-black text-base\">✓ 06</span>
        <p class=\"text-xs text-gray-700 dark:text-zinc-200 font-semibold leading-relaxed\">
          Mengembangkan ilmu pengetahuan dan mencerdaskan kehidupan bangsa.
        </p>
      </div>
    </div>
  </div>

</div>', NULL, NULL, '1', '1', '2026-07-21 02:51:57', '2026-07-27 01:57:13');
INSERT INTO `ppid_pages` (`id`, `slug`, `title`, `icon`, `content`, `meta_title`, `meta_description`, `sort_order`, `is_published`, `created_at`, `updated_at`) VALUES ('2', 'profil', 'Profil Singkat PPID', 'User', '<div class=\"space-y-10\">

  <!-- Overview -->
  <div class=\"p-6 bg-gradient-to-br from-blue-50 to-indigo-50/70 dark:from-zinc-800/60 dark:to-zinc-800/30 border border-blue-100 dark:border-zinc-700/60 rounded-2xl flex items-start gap-4\">
    <div class=\"w-12 h-12 rounded-xl bg-blue-600 text-white flex items-center justify-center text-xl shrink-0 shadow-md\">
      🏛️
    </div>
    <div class=\"space-y-1\">
      <h3 class=\"text-sm font-extrabold text-gray-900 dark:text-zinc-100\">Profil PPID Disdukcapil Kabupaten Dompu</h3>
      <p class=\"text-xs text-gray-600 dark:text-zinc-300 leading-relaxed\">
        PPID Dinas Kependudukan dan Pencatatan Sipil Kabupaten Dompu dibentuk sebagai amanat dari Undang-Undang Nomor 14 Tahun 2008 tentang Keterbukaan Informasi Publik. PPID berperan sebagai jembatan resmi antara masyarakat dengan informasi publik yang dikelola oleh instansi.
      </p>
    </div>
  </div>

  <!-- Struktur Organisasi Cards -->
  <div class=\"space-y-4\">
    <div class=\"flex items-center gap-2 border-b border-gray-100 dark:border-zinc-800 pb-3\">
      <span class=\"text-lg\">👥</span>
      <h3 class=\"text-lg font-black text-gray-900 dark:text-zinc-50 tracking-tight\">Struktur PPID Disdukcapil Dompu</h3>
    </div>

    <div class=\"grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-4\">
      <div class=\"p-4 bg-white dark:bg-zinc-800/50 border border-gray-100 dark:border-zinc-700/60 rounded-2xl space-y-2 text-center shadow-xs\">
        <div style=\"background-color: #dbeafe; color: #1d4ed8;\" class=\"w-10 h-10 mx-auto rounded-full flex items-center justify-center font-bold text-sm\">
          👑
        </div>
        <div>
          <span style=\"background-color: #eff6ff; color: #2563eb;\" class=\"px-2 py-0.5 text-[10px] font-black uppercase rounded tracking-wider\">Atasan PPID</span>
          <h4 class=\"text-xs font-extrabold text-gray-900 dark:text-zinc-100 mt-1\">Kepala Dinas</h4>
          <p class=\"text-[11px] text-gray-400 font-medium\">Pengarah &amp; Penanggung Jawab</p>
        </div>
      </div>

      <div class=\"p-4 bg-white dark:bg-zinc-800/50 border border-gray-100 dark:border-zinc-700/60 rounded-2xl space-y-2 text-center shadow-xs\">
        <div style=\"background-color: #e0e7ff; color: #4338ca;\" class=\"w-10 h-10 mx-auto rounded-full flex items-center justify-center font-bold text-sm\">
          ⭐
        </div>
        <div>
          <span style=\"background-color: #eef2ff; color: #4f46e5;\" class=\"px-2 py-0.5 text-[10px] font-black uppercase rounded tracking-wider\">PPID Utama</span>
          <h4 class=\"text-xs font-extrabold text-gray-900 dark:text-zinc-100 mt-1\">Sekretaris Dinas</h4>
          <p class=\"text-[11px] text-gray-400 font-medium\">Koordinator Utama Layanan</p>
        </div>
      </div>

      <div class=\"p-4 bg-white dark:bg-zinc-800/50 border border-gray-100 dark:border-zinc-700/60 rounded-2xl space-y-2 text-center shadow-xs\">
        <div style=\"background-color: #f3e8ff; color: #7e22ce;\" class=\"w-10 h-10 mx-auto rounded-full flex items-center justify-center font-bold text-sm\">
          📁
        </div>
        <div>
          <span style=\"background-color: #faf5ff; color: #9333ea;\" class=\"px-2 py-0.5 text-[10px] font-black uppercase rounded tracking-wider\">PPID Pelaksana</span>
          <h4 class=\"text-xs font-extrabold text-gray-900 dark:text-zinc-100 mt-1\">Kasubbag Umum</h4>
          <p class=\"text-[11px] text-gray-400 font-medium\">Pengelola Dokumen &amp; Arsip</p>
        </div>
      </div>

      <div class=\"p-4 bg-white dark:bg-zinc-800/50 border border-gray-100 dark:border-zinc-700/60 rounded-2xl space-y-2 text-center shadow-xs\">
        <div style=\"background-color: #d1fae5; color: #047857;\" class=\"w-10 h-10 mx-auto rounded-full flex items-center justify-center font-bold text-sm\">
          🎧
        </div>
        <div>
          <span style=\"background-color: #ecfdf5; color: #059669;\" class=\"px-2 py-0.5 text-[10px] font-black uppercase rounded tracking-wider\">Petugas Desk</span>
          <h4 class=\"text-xs font-extrabold text-gray-900 dark:text-zinc-100 mt-1\">Staf Subbag Umum</h4>
          <p class=\"text-[11px] text-gray-400 font-medium\">Frontdesk Layanan Pemohon</p>
        </div>
      </div>
    </div>
  </div>

  <!-- Visi & Misi -->
  <div class=\"space-y-6\">
    <!-- Visi -->
    <div class=\"p-6 bg-gradient-to-r from-amber-500 to-amber-400 text-slate-950 rounded-2xl shadow-md space-y-1\">
      <span style=\"background-color: #020617; color: #fcd34d;\" class=\"text-[10px] font-black uppercase tracking-widest px-2.5 py-0.5 rounded-md\">Visi PPID</span>
      <h3 class=\"text-base sm:text-lg font-black leading-snug mt-2\">
        \"Terwujudnya Pelayanan Informasi Publik yang Transparan, Akuntabel, Cepat, dan Berkualitas di Disdukcapil Kabupaten Dompu\"
      </h3>
    </div>

    <!-- Misi -->
    <div class=\"space-y-3\">
      <h4 class=\"text-sm font-black text-gray-900 dark:text-zinc-100 flex items-center gap-2\">
        <span>🚀</span> Misi Pelaksanaan PPID:
      </h4>

      <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">
        <!-- Misi 01 -->
        <div class=\"p-4 bg-slate-50/70 dark:bg-zinc-800/40 border border-gray-100 dark:border-zinc-800 rounded-2xl flex items-start gap-3\">
          <div style=\"background-color: #2563eb; color: #ffffff;\" class=\"w-7 h-7 rounded-lg font-black text-xs flex items-center justify-center shrink-0 shadow-xs\">01</div>
          <p class=\"text-xs text-gray-700 dark:text-zinc-200 font-medium leading-relaxed mt-0.5\">
            Mengelola dan mendokumentasikan arsip informasi publik secara akurat dan profesional.
          </p>
        </div>

        <!-- Misi 02 -->
        <div class=\"p-4 bg-slate-50/70 dark:bg-zinc-800/40 border border-gray-100 dark:border-zinc-800 rounded-2xl flex items-start gap-3\">
          <div style=\"background-color: #4f46e5; color: #ffffff;\" class=\"w-7 h-7 rounded-lg font-black text-xs flex items-center justify-center shrink-0 shadow-xs\">02</div>
          <p class=\"text-xs text-gray-700 dark:text-zinc-200 font-medium leading-relaxed mt-0.5\">
            Memberikan pelayanan informasi publik secara cepat, tepat waktu, biaya ringan, dan sederhana.
          </p>
        </div>

        <!-- Misi 03 -->
        <div class=\"p-4 bg-slate-50/70 dark:bg-zinc-800/40 border border-gray-100 dark:border-zinc-800 rounded-2xl flex items-start gap-3\">
          <div style=\"background-color: #9333ea; color: #ffffff;\" class=\"w-7 h-7 rounded-lg font-black text-xs flex items-center justify-center shrink-0 shadow-xs\">03</div>
          <p class=\"text-xs text-gray-700 dark:text-zinc-200 font-medium leading-relaxed mt-0.5\">
            Meningkatkan kompetensi dan integritas SDM pengelola layanan informasi secara berkelanjutan.
          </p>
        </div>

        <!-- Misi 04 -->
        <div class=\"p-4 bg-slate-50/70 dark:bg-zinc-800/40 border border-gray-100 dark:border-zinc-800 rounded-2xl flex items-start gap-3\">
          <div style=\"background-color: #059669; color: #ffffff;\" class=\"w-7 h-7 rounded-lg font-black text-xs flex items-center justify-center shrink-0 shadow-xs\">04</div>
          <p class=\"text-xs text-gray-700 dark:text-zinc-200 font-medium leading-relaxed mt-0.5\">
            Membangun sistem pelayanan informasi digital yang terintegrasi, transparan, dan teruji.
          </p>
        </div>
      </div>
    </div>
  </div>

</div>', NULL, NULL, '2', '1', '2026-07-21 02:51:57', '2026-07-27 01:57:13');
INSERT INTO `ppid_pages` (`id`, `slug`, `title`, `icon`, `content`, `meta_title`, `meta_description`, `sort_order`, `is_published`, `created_at`, `updated_at`) VALUES ('3', 'tugas-fungsi', 'Tugas dan Fungsi PPID', 'ClipboardList', '<div class=\"space-y-10\">

  <!-- Header Banner / Dasar Hukum -->
  <div class=\"p-6 bg-gradient-to-br from-blue-50 to-indigo-50/70 dark:from-zinc-800/60 dark:to-zinc-800/30 border border-blue-100 dark:border-zinc-700/60 rounded-2xl flex items-start gap-4\">
    <div class=\"w-12 h-12 rounded-xl bg-blue-600 text-white flex items-center justify-center text-xl shrink-0 shadow-md\">
      📜
    </div>
    <div class=\"space-y-1\">
      <h3 class=\"text-sm font-extrabold text-gray-900 dark:text-zinc-100\">Dasar Hukum &amp; Mandat PPID</h3>
      <p class=\"text-xs text-gray-600 dark:text-zinc-300 leading-relaxed\">
        Berdasarkan <strong>Undang-Undang No. 14 Tahun 2008</strong> tentang Keterbukaan Informasi Publik (UU KIP) serta peraturan pelaksanaannya, Pejabat Pengelola Informasi dan Dokumentasi (PPID) Disdukcapil Kabupaten Dompu memiliki tugas dan fungsi sebagai berikut:
      </p>
    </div>
  </div>

  <!-- Section 1: Tugas PPID -->
  <div class=\"space-y-4\">
    <div class=\"flex items-center gap-2 border-b border-gray-100 dark:border-zinc-800 pb-3\">
      <span class=\"text-lg\">📋</span>
      <h3 class=\"text-lg font-black text-gray-900 dark:text-zinc-50 tracking-tight\">Tugas Utama PPID</h3>
    </div>

    <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">
      <!-- Task 1 -->
      <div class=\"p-5 bg-white dark:bg-zinc-800/50 border border-gray-100 dark:border-zinc-700/60 rounded-2xl flex items-start gap-3.5 shadow-xs hover:border-blue-300 transition\">
        <div style=\"background-color: #2563eb; color: #ffffff;\" class=\"w-8 h-8 rounded-xl font-black text-xs flex items-center justify-center shrink-0 shadow-xs\">
          01
        </div>
        <p class=\"text-xs text-gray-700 dark:text-zinc-200 font-medium leading-relaxed mt-1\">
          Menyediakan, memberikan, dan/atau menerbitkan informasi publik yang diminta oleh pemohon informasi secara akurat dan tepat waktu.
        </p>
      </div>

      <!-- Task 2 -->
      <div class=\"p-5 bg-white dark:bg-zinc-800/50 border border-gray-100 dark:border-zinc-700/60 rounded-2xl flex items-start gap-3.5 shadow-xs hover:border-blue-300 transition\">
        <div style=\"background-color: #d97706; color: #ffffff;\" class=\"w-8 h-8 rounded-xl font-black text-xs flex items-center justify-center shrink-0 shadow-xs\">
          02
        </div>
        <p class=\"text-xs text-gray-700 dark:text-zinc-200 font-medium leading-relaxed mt-1\">
          Menyampaikan pemberitahuan tertulis perihal informasi yang dikecualikan sesuai dengan pertimbangan konsekuensi hukum.
        </p>
      </div>

      <!-- Task 3 -->
      <div class=\"p-5 bg-white dark:bg-zinc-800/50 border border-gray-100 dark:border-zinc-700/60 rounded-2xl flex items-start gap-3.5 shadow-xs hover:border-blue-300 transition\">
        <div style=\"background-color: #e11d48; color: #ffffff;\" class=\"w-8 h-8 rounded-xl font-black text-xs flex items-center justify-center shrink-0 shadow-xs\">
          03
        </div>
        <p class=\"text-xs text-gray-700 dark:text-zinc-200 font-medium leading-relaxed mt-1\">
          Menolak permohonan informasi secara resmi apabila tidak memenuhi ketentuan perundang-undangan yang berlaku.
        </p>
      </div>

      <!-- Task 4 -->
      <div class=\"p-5 bg-white dark:bg-zinc-800/50 border border-gray-100 dark:border-zinc-700/60 rounded-2xl flex items-start gap-3.5 shadow-xs hover:border-blue-300 transition\">
        <div style=\"background-color: #059669; color: #ffffff;\" class=\"w-8 h-8 rounded-xl font-black text-xs flex items-center justify-center shrink-0 shadow-xs\">
          04
        </div>
        <p class=\"text-xs text-gray-700 dark:text-zinc-200 font-medium leading-relaxed mt-1\">
          Menyimpan, mendokumentasikan, menyediakan, dan memberi pelayanan informasi publik secara profesional.
        </p>
      </div>
    </div>
  </div>

  <!-- Section 2: Fungsi PPID -->
  <div class=\"space-y-4\">
    <div class=\"flex items-center gap-2 border-b border-gray-100 dark:border-zinc-800 pb-3\">
      <span class=\"text-lg\">⚙️</span>
      <h3 class=\"text-lg font-black text-gray-900 dark:text-zinc-50 tracking-tight\">Fungsi Pelaksanaan PPID</h3>
    </div>

    <div class=\"grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-4\">
      <!-- Function 1 -->
      <div class=\"p-4 bg-slate-50/70 dark:bg-zinc-800/40 border border-gray-100 dark:border-zinc-800 rounded-2xl space-y-1.5\">
        <div class=\"flex items-center gap-2\">
          <span style=\"background-color: #2563eb;\" class=\"w-2.5 h-2.5 rounded-full inline-block\"></span>
          <h4 class=\"text-xs font-extrabold text-gray-900 dark:text-zinc-100\">Perencanaan</h4>
        </div>
        <p class=\"text-[11px] text-gray-500 dark:text-zinc-400 leading-relaxed\">
          Menyusun rencana dan kebijakan pengumpulan serta pengelolaan informasi publik.
        </p>
      </div>

      <!-- Function 2 -->
      <div class=\"p-4 bg-slate-50/70 dark:bg-zinc-800/40 border border-gray-100 dark:border-zinc-800 rounded-2xl space-y-1.5\">
        <div class=\"flex items-center gap-2\">
          <span style=\"background-color: #4f46e5;\" class=\"w-2.5 h-2.5 rounded-full inline-block\"></span>
          <h4 class=\"text-xs font-extrabold text-gray-900 dark:text-zinc-100\">Pengorganisasian</h4>
        </div>
        <p class=\"text-[11px] text-gray-500 dark:text-zinc-400 leading-relaxed\">
          Mengkoordinasikan dan mengkonsolidasikan pengumpulan bahan informasi dari seluruh bidang.
        </p>
      </div>

      <!-- Function 3 -->
      <div class=\"p-4 bg-slate-50/70 dark:bg-zinc-800/40 border border-gray-100 dark:border-zinc-800 rounded-2xl space-y-1.5\">
        <div class=\"flex items-center gap-2\">
          <span style=\"background-color: #9333ea;\" class=\"w-2.5 h-2.5 rounded-full inline-block\"></span>
          <h4 class=\"text-xs font-extrabold text-gray-900 dark:text-zinc-100\">Penyimpanan</h4>
        </div>
        <p class=\"text-[11px] text-gray-500 dark:text-zinc-400 leading-relaxed\">
          Menyimpan dan mendokumentasikan arsip informasi publik dari setiap unit kerja.
        </p>
      </div>

      <!-- Function 4 -->
      <div class=\"p-4 bg-slate-50/70 dark:bg-zinc-800/40 border border-gray-100 dark:border-zinc-800 rounded-2xl space-y-1.5\">
        <div class=\"flex items-center gap-2\">
          <span style=\"background-color: #059669;\" class=\"w-2.5 h-2.5 rounded-full inline-block\"></span>
          <h4 class=\"text-xs font-extrabold text-gray-900 dark:text-zinc-100\">Pelayanan</h4>
        </div>
        <p class=\"text-[11px] text-gray-500 dark:text-zinc-400 leading-relaxed\">
          Memberikan pelayanan informasi cepat, ramah, dan transparan kepada masyarakat.
        </p>
      </div>

      <!-- Function 5 -->
      <div class=\"p-4 bg-slate-50/70 dark:bg-zinc-800/40 border border-gray-100 dark:border-zinc-800 rounded-2xl space-y-1.5\">
        <div class=\"flex items-center gap-2\">
          <span style=\"background-color: #d97706;\" class=\"w-2.5 h-2.5 rounded-full inline-block\"></span>
          <h4 class=\"text-xs font-extrabold text-gray-900 dark:text-zinc-100\">Penetapan</h4>
        </div>
        <p class=\"text-[11px] text-gray-500 dark:text-zinc-400 leading-relaxed\">
          Menetapkan klasifikasi informasi yang dikecualikan dari akses publik sesuai regulasi.
        </p>
      </div>

      <!-- Function 6 -->
      <div class=\"p-4 bg-slate-50/70 dark:bg-zinc-800/40 border border-gray-100 dark:border-zinc-800 rounded-2xl space-y-1.5\">
        <div class=\"flex items-center gap-2\">
          <span style=\"background-color: #e11d48;\" class=\"w-2.5 h-2.5 rounded-full inline-block\"></span>
          <h4 class=\"text-xs font-extrabold text-gray-900 dark:text-zinc-100\">Pengujian</h4>
        </div>
        <p class=\"text-[11px] text-gray-500 dark:text-zinc-400 leading-relaxed\">
          Melakukan uji konsekuensi sebelum menetapkan suatu informasi sebagai rahasia/dikecualikan.
        </p>
      </div>
    </div>
  </div>

  <!-- Section 3: Jenis Informasi Publik (High Contrast Soft Cards) -->
  <div class=\"space-y-4\">
    <div class=\"flex items-center gap-2 border-b border-gray-100 dark:border-zinc-800 pb-3\">
      <span class=\"text-lg\">📊</span>
      <h3 class=\"text-lg font-black text-gray-900 dark:text-zinc-50 tracking-tight\">Kategori / Jenis Informasi Publik</h3>
    </div>

    <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">
      <!-- Jenis 1 -->
      <div class=\"p-5 bg-blue-50/90 dark:bg-blue-950/40 border border-blue-200 dark:border-blue-800/60 rounded-2xl space-y-2 shadow-xs\">
        <div class=\"flex items-center gap-2\">
          <span class=\"text-base\">📅</span>
          <h4 class=\"text-sm font-black text-blue-950 dark:text-blue-100\">Informasi Berkala</h4>
        </div>
        <p class=\"text-xs text-blue-900/80 dark:text-blue-200 leading-relaxed font-medium\">
          Informasi yang wajib disediakan dan diumumkan secara rutin &amp; berkala kepada masyarakat.
        </p>
      </div>

      <!-- Jenis 2 -->
      <div class=\"p-5 bg-emerald-50/90 dark:bg-emerald-950/40 border border-emerald-200 dark:border-emerald-800/60 rounded-2xl space-y-2 shadow-xs\">
        <div class=\"flex items-center gap-2\">
          <span class=\"text-base\">⚡</span>
          <h4 class=\"text-sm font-black text-emerald-950 dark:text-emerald-100\">Informasi Serta-Merta</h4>
        </div>
        <p class=\"text-xs text-emerald-900/80 dark:text-emerald-200 leading-relaxed font-medium\">
          Informasi yang dapat mengancam hajat hidup orang banyak dan ketertiban umum yang wajib diumumkan seketika.
        </p>
      </div>

      <!-- Jenis 3 -->
      <div class=\"p-5 bg-indigo-50/90 dark:bg-indigo-950/40 border border-indigo-200 dark:border-indigo-800/60 rounded-2xl space-y-2 shadow-xs\">
        <div class=\"flex items-center gap-2\">
          <span class=\"text-base\">📂</span>
          <h4 class=\"text-sm font-black text-indigo-950 dark:text-indigo-100\">Informasi Setiap Saat</h4>
        </div>
        <p class=\"text-xs text-indigo-900/80 dark:text-indigo-200 leading-relaxed font-medium\">
          Informasi publik yang wajib tersedia setiap saat dan siap diberikan sewaktu-waktu saat dimohonkan.
        </p>
      </div>

      <!-- Jenis 4 -->
      <div class=\"p-5 bg-amber-50/90 dark:bg-amber-950/40 border border-amber-200 dark:border-amber-800/60 rounded-2xl space-y-2 shadow-xs\">
        <div class=\"flex items-center gap-2\">
          <span class=\"text-base\">🔒</span>
          <h4 class=\"text-sm font-black text-amber-950 dark:text-amber-100\">Informasi Dikecualikan</h4>
        </div>
        <p class=\"text-xs text-amber-900/80 dark:text-amber-200 leading-relaxed font-medium\">
          Informasi bersifat rahasia yang tidak dapat diakses publik berdasarkan pengujian konsekuensi UU KIP.
        </p>
      </div>
    </div>
  </div>

</div>', NULL, NULL, '3', '1', '2026-07-21 02:51:57', '2026-07-27 01:57:13');
INSERT INTO `ppid_pages` (`id`, `slug`, `title`, `icon`, `content`, `meta_title`, `meta_description`, `sort_order`, `is_published`, `created_at`, `updated_at`) VALUES ('4', 'kontak', 'Kontak PPID', 'Phone', '<div class=\"space-y-10\">

  <!-- Callout Header -->
  <div class=\"p-6 bg-gradient-to-br from-blue-50 to-indigo-50/70 dark:from-zinc-800/60 dark:to-zinc-800/30 border border-blue-100 dark:border-zinc-700/60 rounded-2xl flex items-start gap-4\">
    <div class=\"w-12 h-12 rounded-xl bg-blue-600 text-white flex items-center justify-center text-xl shrink-0 shadow-md\">
      📞
    </div>
    <div class=\"space-y-1\">
      <h3 class=\"text-sm font-extrabold text-gray-900 dark:text-zinc-100\">Pusat Layanan &amp; Informasi PPID</h3>
      <p class=\"text-xs text-gray-600 dark:text-zinc-300 leading-relaxed\">
        Silakan hubungi atau kunjungi Kantor Desk PPID Disdukcapil Kabupaten Dompu untuk mengajukan permohonan informasi publik, konfirmasi, atau konsultasi.
      </p>
    </div>
  </div>

  <!-- Contact Cards Grid -->
  <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">
    <!-- Alamat -->
    <div class=\"p-5 bg-white dark:bg-zinc-800/50 border border-gray-100 dark:border-zinc-700/60 rounded-2xl space-y-2 shadow-xs\">
      <div class=\"flex items-center gap-2\">
        <span class=\"text-lg\">📍</span>
        <h4 class=\"text-xs font-black text-gray-900 dark:text-zinc-100\">Alamat Kantor Desk PPID</h4>
      </div>
      <p class=\"text-xs text-gray-600 dark:text-zinc-300 leading-relaxed font-medium\">
        Dinas Kependudukan dan Pencatatan Sipil Kab. Dompu<br>
        Jl. Soekarno-Hatta No. 1, Dompu, Nusa Tenggara Barat (84211)
      </p>
    </div>

    <!-- Telepon -->
    <div class=\"p-5 bg-white dark:bg-zinc-800/50 border border-gray-100 dark:border-zinc-700/60 rounded-2xl space-y-2 shadow-xs\">
      <div class=\"flex items-center gap-2\">
        <span class=\"text-lg\">📞</span>
        <h4 class=\"text-xs font-black text-gray-900 dark:text-zinc-100\">Telepon &amp; Call Center</h4>
      </div>
      <p class=\"text-xs text-gray-600 dark:text-zinc-300 leading-relaxed font-medium\">
        (0373) 21124 / 21000<br>
        <span class=\"text-[11px] text-gray-400\">Petugas Desk PPID Siap Melayani saat Jam Kerja</span>
      </p>
    </div>

    <!-- Email -->
    <div class=\"p-5 bg-white dark:bg-zinc-800/50 border border-gray-100 dark:border-zinc-700/60 rounded-2xl space-y-2 shadow-xs\">
      <div class=\"flex items-center gap-2\">
        <span class=\"text-lg\">📧</span>
        <h4 class=\"text-xs font-black text-gray-900 dark:text-zinc-100\">Email Resmi PPID</h4>
      </div>
      <p class=\"text-xs text-gray-600 dark:text-zinc-300 leading-relaxed font-medium\">
        ppid@dukcapil.dompukab.go.id<br>
        <span class=\"text-[11px] text-gray-400\">Balasan Permohonan via Surat Elektronik Official</span>
      </p>
    </div>

    <!-- Jam Layanan -->
    <div class=\"p-5 bg-white dark:bg-zinc-800/50 border border-gray-100 dark:border-zinc-700/60 rounded-2xl space-y-2 shadow-xs\">
      <div class=\"flex items-center gap-2\">
        <span class=\"text-lg\">🕐</span>
        <h4 class=\"text-xs font-black text-gray-900 dark:text-zinc-100\">Jam Operasional Layanan</h4>
      </div>
      <p class=\"text-xs text-gray-600 dark:text-zinc-300 leading-relaxed font-medium\">
        Senin – Kamis: 08.00 – 16.00 WITA<br>
        Jumat: 08.00 – 11.30 WITA
      </p>
    </div>
  </div>

  <!-- Mekanisme Permohonan Timeline -->
  <div class=\"space-y-4\">
    <div class=\"flex items-center gap-2 border-b border-gray-100 dark:border-zinc-800 pb-3\">
      <span class=\"text-lg\">🔄</span>
      <h3 class=\"text-lg font-black text-gray-900 dark:text-zinc-50 tracking-tight\">Mekanisme Alur Permohonan Informasi</h3>
    </div>

    <div class=\"space-y-3\">
      <!-- Step 1 -->
      <div class=\"p-4 bg-slate-50/70 dark:bg-zinc-800/40 border border-gray-100 dark:border-zinc-800 rounded-2xl flex items-start gap-3.5\">
        <div style=\"background-color: #2563eb; color: #ffffff;\" class=\"w-8 h-8 rounded-full font-black text-xs flex items-center justify-center shrink-0 shadow-xs\">1</div>
        <div class=\"min-w-0 flex-1\">
          <h4 class=\"text-xs font-extrabold text-gray-900 dark:text-zinc-100\">Pengajuan Permohonan</h4>
          <p class=\"text-[11px] text-gray-500 dark:text-zinc-400 mt-0.5 leading-relaxed\">
            Pemohon mengisi formulir permohonan informasi secara online via website atau datang langsung ke Desk PPID.
          </p>
        </div>
      </div>

      <!-- Step 2 -->
      <div class=\"p-4 bg-slate-50/70 dark:bg-zinc-800/40 border border-gray-100 dark:border-zinc-800 rounded-2xl flex items-start gap-3.5\">
        <div style=\"background-color: #4f46e5; color: #ffffff;\" class=\"w-8 h-8 rounded-full font-black text-xs flex items-center justify-center shrink-0 shadow-xs\">2</div>
        <div class=\"min-w-0 flex-1\">
          <h4 class=\"text-xs font-extrabold text-gray-900 dark:text-zinc-100\">Verifikasi Identitas</h4>
          <p class=\"text-[11px] text-gray-500 dark:text-zinc-400 mt-0.5 leading-relaxed\">
            Petugas melakukan verifikasi kelengkapan identitas perorangan (KTP-el) atau berkas badan hukum/organisasi.
          </p>
        </div>
      </div>

      <!-- Step 3 -->
      <div class=\"p-4 bg-slate-50/70 dark:bg-zinc-800/40 border border-gray-100 dark:border-zinc-800 rounded-2xl flex items-start gap-3.5\">
        <div style=\"background-color: #9333ea; color: #ffffff;\" class=\"w-8 h-8 rounded-full font-black text-xs flex items-center justify-center shrink-0 shadow-xs\">3</div>
        <div class=\"min-w-0 flex-1\">
          <h4 class=\"text-xs font-extrabold text-gray-900 dark:text-zinc-100\">Pencatatan Register Permohonan</h4>
          <p class=\"text-[11px] text-gray-500 dark:text-zinc-400 mt-0.5 leading-relaxed\">
            Permohonan dicatat dalam Buku Register PPID dan pemohon menerima bukti tanda terima pendaftaran.
          </p>
        </div>
      </div>

      <!-- Step 4 -->
      <div class=\"p-4 bg-slate-50/70 dark:bg-zinc-800/40 border border-gray-100 dark:border-zinc-800 rounded-2xl flex items-start gap-3.5\">
        <div style=\"background-color: #d97706; color: #ffffff;\" class=\"w-8 h-8 rounded-full font-black text-xs flex items-center justify-center shrink-0 shadow-xs\">4</div>
        <div class=\"min-w-0 flex-1\">
          <h4 class=\"text-xs font-extrabold text-gray-900 dark:text-zinc-100\">Pemrosesan &amp; Pengujian (Maksimal 10 Hari Kerja)</h4>
          <p class=\"text-[11px] text-gray-500 dark:text-zinc-400 mt-0.5 leading-relaxed\">
            PPID memproses &amp; berkoordinasi dengan bidang terkait. PPID wajib memberikan tanggapan resmi maksimal <strong>10 hari kerja</strong> (dapat diperpanjang 7 hari kerja dengan pemberitahuan).
          </p>
        </div>
      </div>

      <!-- Step 5 -->
      <div class=\"p-4 bg-slate-50/70 dark:bg-zinc-800/40 border border-gray-100 dark:border-zinc-800 rounded-2xl flex items-start gap-3.5\">
        <div style=\"background-color: #059669; color: #ffffff;\" class=\"w-8 h-8 rounded-full font-black text-xs flex items-center justify-center shrink-0 shadow-xs\">5</div>
        <div class=\"min-w-0 flex-1\">
          <h4 class=\"text-xs font-extrabold text-gray-900 dark:text-zinc-100\">Penyampaian Keputusan &amp; Penyerahan Informasi</h4>
          <p class=\"text-[11px] text-gray-500 dark:text-zinc-400 mt-0.5 leading-relaxed\">
            Informasi publik diserahkan secara gratis (tanpa biaya) atau surat pemberitahuan alasan apabila informasi dikecualikan.
          </p>
        </div>
      </div>
    </div>
  </div>

</div>', NULL, NULL, '4', '1', '2026-07-21 02:51:57', '2026-07-27 01:56:12');
INSERT INTO `ppid_pages` (`id`, `slug`, `title`, `icon`, `content`, `meta_title`, `meta_description`, `sort_order`, `is_published`, `created_at`, `updated_at`) VALUES ('5', 'sk-ppid', 'SK PPID Dinas Dukcapil', 'FileCheck', '<div class=\"space-y-10\">

  <!-- Callout Banner -->
  <div class=\"p-6 bg-gradient-to-br from-blue-50 to-indigo-50/70 dark:from-zinc-800/60 dark:to-zinc-800/30 border border-blue-100 dark:border-zinc-700/60 rounded-2xl flex items-start gap-4\">
    <div class=\"w-12 h-12 rounded-xl bg-blue-600 text-white flex items-center justify-center text-xl shrink-0 shadow-md\">
      📁
    </div>
    <div class=\"space-y-1\">
      <h3 class=\"text-sm font-extrabold text-gray-900 dark:text-zinc-100\">Surat Keputusan (SK) Resmi PPID</h3>
      <p class=\"text-xs text-gray-600 dark:text-zinc-300 leading-relaxed\">
        Daftar Surat Keputusan (SK) Kepala Dinas Kependudukan dan Pencatatan Sipil Kabupaten Dompu terkait penetapan pengelola, SOP, daftar informasi publik, serta daftar informasi yang dikecualikan.
      </p>
    </div>
  </div>

  <!-- Document List Grid -->
  <div class=\"space-y-4\">
    <div class=\"flex items-center gap-2 border-b border-gray-100 dark:border-zinc-800 pb-3\">
      <span class=\"text-lg\">📑</span>
      <h3 class=\"text-lg font-black text-gray-900 dark:text-zinc-50 tracking-tight\">Daftar Dokumen SK PPID</h3>
    </div>

    <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">
      <!-- SK 1 -->
      <div class=\"p-5 bg-white dark:bg-zinc-800/50 border border-gray-100 dark:border-zinc-700/60 rounded-2xl space-y-3 shadow-xs hover:border-blue-300 transition\">
        <div class=\"flex items-center gap-3\">
          <div class=\"w-10 h-10 rounded-xl bg-blue-50 dark:bg-blue-950 text-blue-600 dark:text-blue-300 flex items-center justify-center font-bold text-lg shrink-0\">
            📄
          </div>
          <div>
            <h4 class=\"text-xs font-extrabold text-gray-900 dark:text-zinc-100 leading-snug\">
              SK Penetapan Struktur PPID Disdukcapil
            </h4>
            <p class=\"text-[10px] text-gray-400 font-mono mt-0.5\">Format PDF • Resmi</p>
          </div>
        </div>
        <p class=\"text-[11px] text-gray-500 dark:text-zinc-400 leading-relaxed\">
          SK Kepala Dinas tentang Pembentukan &amp; Penetapan Pejabat Pengelola Informasi dan Dokumentasi (PPID).
        </p>
      </div>

      <!-- SK 2 -->
      <div class=\"p-5 bg-white dark:bg-zinc-800/50 border border-gray-100 dark:border-zinc-700/60 rounded-2xl space-y-3 shadow-xs hover:border-blue-300 transition\">
        <div class=\"flex items-center gap-3\">
          <div class=\"w-10 h-10 rounded-xl bg-emerald-50 dark:bg-emerald-950 text-emerald-600 dark:text-emerald-300 flex items-center justify-center font-bold text-lg shrink-0\">
            📊
          </div>
          <div>
            <h4 class=\"text-xs font-extrabold text-gray-900 dark:text-zinc-100 leading-snug\">
              SK Daftar Informasi Publik (DIP)
            </h4>
            <p class=\"text-[10px] text-gray-400 font-mono mt-0.5\">Format PDF • Berkelanjutan</p>
          </div>
        </div>
        <p class=\"text-[11px] text-gray-500 dark:text-zinc-400 leading-relaxed\">
          SK tentang Rincian Penetapan Daftar Informasi Publik yang Terbuka dan Wajib Disediakan.
        </p>
      </div>

      <!-- SK 3 -->
      <div class=\"p-5 bg-white dark:bg-zinc-800/50 border border-gray-100 dark:border-zinc-800 rounded-2xl space-y-3 shadow-xs hover:border-blue-300 transition\">
        <div class=\"flex items-center gap-3\">
          <div class=\"w-10 h-10 rounded-xl bg-amber-50 dark:bg-amber-950 text-amber-600 dark:text-amber-300 flex items-center justify-center font-bold text-lg shrink-0\">
            🔒
          </div>
          <div>
            <h4 class=\"text-xs font-extrabold text-gray-900 dark:text-zinc-100 leading-snug\">
              SK Daftar Informasi yang Dikecualikan
            </h4>
            <p class=\"text-[10px] text-gray-400 font-mono mt-0.5\">Format PDF • Teruji Uu KIP</p>
          </div>
        </div>
        <p class=\"text-[11px] text-gray-500 dark:text-zinc-400 leading-relaxed\">
          SK tentang Hasil Uji Konsekuensi Informasi Publik yang Bersifat Rahasia/Dikecualikan.
        </p>
      </div>

      <!-- SK 4 -->
      <div class=\"p-5 bg-white dark:bg-zinc-800/50 border border-gray-100 dark:border-zinc-700/60 rounded-2xl space-y-3 shadow-xs hover:border-blue-300 transition\">
        <div class=\"flex items-center gap-3\">
          <div class=\"w-10 h-10 rounded-xl bg-purple-50 dark:bg-purple-950 text-purple-600 dark:text-purple-300 flex items-center justify-center font-bold text-lg shrink-0\">
            📋
          </div>
          <div>
            <h4 class=\"text-xs font-extrabold text-gray-900 dark:text-zinc-100 leading-snug\">
              SK Standard Operating Procedure (SOP) PPID
            </h4>
            <p class=\"text-[10px] text-gray-400 font-mono mt-0.5\">Format PDF • Standar Pelayanan</p>
          </div>
        </div>
        <p class=\"text-[11px] text-gray-500 dark:text-zinc-400 leading-relaxed\">
          SOP Pengelolaan, Pelayanan, Pengajuan Keberatan, dan Penanganan Sengketa Informasi Publik.
        </p>
      </div>
    </div>
  </div>

</div>', NULL, NULL, '5', '1', '2026-07-21 02:51:57', '2026-07-27 01:52:10');

DROP TABLE IF EXISTS `ppid_requests`;
CREATE TABLE `ppid_requests` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `ticket_number` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `requester_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `requester_email` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `requester_phone` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `requester_address` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `requester_id_number` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `purpose` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `information_requested` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `request_method` enum('online','langsung','surat') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'online',
  `delivery_method` enum('email','langsung','salinan') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'email',
  `status` enum('diterima','diproses','selesai','ditolak') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'diterima',
  `response_notes` text COLLATE utf8mb4_unicode_ci,
