DROP TABLE IF EXISTS `rts`;
CREATE TABLE `rts` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `rw_id` bigint unsigned NOT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `number` smallint unsigned NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `rts_rw_id_foreign` (`rw_id`),
  CONSTRAINT `rts_rw_id_foreign` FOREIGN KEY (`rw_id`) REFERENCES `rws` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `rws`;
CREATE TABLE `rws` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `dusun_id` bigint unsigned NOT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `number` smallint unsigned NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `rws_dusun_id_foreign` (`dusun_id`),
  CONSTRAINT `rws_dusun_id_foreign` FOREIGN KEY (`dusun_id`) REFERENCES `dusuns` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `service_requirements`;
CREATE TABLE `service_requirements` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `icon` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Emoji or Lucide icon name',
  `color` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '#2563eb',
  `description` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `requirements` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'The detailed bullet-point list of requirements',
  `processing_time` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1 Hari Kerja',
  `cost` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Gratis / Rp 0',
  `sort_order` smallint unsigned NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `service_requirements_slug_unique` (`slug`)
) ENGINE=InnoDB AUTO_INCREMENT=103 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `service_requirements` (`id`, `title`, `slug`, `icon`, `color`, `description`, `requirements`, `processing_time`, `cost`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES ('99', 'Perekaman KTP Elektronik', 'perekaman-ktp-elektronik', '🪪', '#2563eb', 'Persyaratan pengajuan perekaman dan pencetakan Kartu Tanda Penduduk Elektronik (KTP-El) baru maupun ganti hilang/rusak.', '<ul>
<li>Telah berusia 17 tahun atau sudah kawin/pernah kawin</li>
<li>Fotokopi Kartu Keluarga (KK) terbaru</li>
<li>Surat Keterangan Kehilangan dari Kepolisian (untuk KTP-El ganti karena hilang)</li>
<li>KTP-El fisik yang rusak (untuk KTP-El ganti karena rusak)</li>
<li>Surat Keterangan Pindah (SKPWNI) jika merupakan warga pindahan baru</li>
</ul>', '1 Hari Kerja', 'Gratis / Rp 0', '1', '1', '2026-07-23 12:06:12', '2026-07-23 12:06:12');
INSERT INTO `service_requirements` (`id`, `title`, `slug`, `icon`, `color`, `description`, `requirements`, `processing_time`, `cost`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES ('100', 'Kartu Identitas Anak (KIA)', 'kartu-identitas-anak', '🧒', '#8b5cf6', 'Persyaratan penerbitan identitas kependudukan bagi anak berusia 0 - 17 tahun kurang satu hari.', '<ul>
<li>Fotokopi Akta Kelahiran Anak</li>
<li>Kartu Keluarga (KK) asli orang tua</li>
<li>KTP asli kedua orang tua</li>
<li>Pas foto anak ukuran 2x3 sebanyak 2 lembar (untuk anak usia 5-17 tahun, warna latar menyesuaikan tahun lahir ganjil/genap)</li>
<li>KIA lama jika ganti rusak/hilang</li>
</ul>', '1 Hari Kerja', 'Gratis / Rp 0', '2', '1', '2026-07-23 12:06:12', '2026-07-23 12:06:12');
INSERT INTO `service_requirements` (`id`, `title`, `slug`, `icon`, `color`, `description`, `requirements`, `processing_time`, `cost`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES ('101', 'Akta Kelahiran & Kematian', 'akta-kelahiran-kematian', '📜', '#10b981', 'Persyaratan pengurusan pencatatan sipil penerbitan Akta Kelahiran baru bagi bayi dan Akta Kematian bagi warga yang telah meninggal.', '<h3>Persyaratan Akta Kelahiran:</h3>
<ul>
<li>Surat Keterangan Kelahiran dari Penolong Kelahiran (Bidan/Rumah Sakit/Puskesmas)</li>
<li>Fotokopi Buku Nikah / Akta Perkawinan Orang Tua</li>
<li>Fotokopi KTP kedua orang tua dan 2 orang saksi</li>
<li>Kartu Keluarga (KK) asli dimana anak akan didaftarkan</li>
</ul>

<h3>Persyaratan Akta Kematian:</h3>
<ul>
<li>Surat Keterangan Kematian dari Dokter/Rumah Sakit atau Kepala Desa/Lurah</li>
<li>KK dan KTP asli yang meninggal</li>
<li>Fotokopi KTP pelapor dan 2 orang saksi</li>
</ul>', '1 Hari Kerja', 'Gratis / Rp 0', '3', '1', '2026-07-23 12:06:12', '2026-07-23 12:06:12');
INSERT INTO `service_requirements` (`id`, `title`, `slug`, `icon`, `color`, `description`, `requirements`, `processing_time`, `cost`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES ('102', 'Kartu Keluarga (KK)', 'kartu-keluarga', '🏠', '#f59e0b', 'Persyaratan penerbitan, penggantian, pemecahan, atau perubahan elemen data pada Kartu Keluarga kependudukan.', '<ul>
<li>KK lama (asli)</li>
<li>Surat Nikah / Akta Cerai (bagi yang baru menikah atau bercerai)</li>
<li>Surat Keterangan Pindah (SKPWNI) bagi anggota keluarga yang pindah masuk</li>
<li>Akta Kelahiran / Ijazah pendukung jika ada penambahan nama/perubahan elemen data pendidikan</li>
<li>Surat Keterangan Kematian (jika ada pengurangan anggota keluarga meninggal)</li>
</ul>', '1 Hari Kerja', 'Gratis / Rp 0', '4', '1', '2026-07-23 12:06:12', '2026-07-23 12:06:12');

