DROP TABLE IF EXISTS `survey_follow_up_actions`;
CREATE TABLE `survey_follow_up_actions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `survey_period_id` bigint unsigned NOT NULL,
  `recommendation_id` bigint unsigned DEFAULT NULL,
  `action_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `responsible_unit` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Bidang PIAK',
  `progress` int NOT NULL DEFAULT '0',
  `evidence_document` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `completion_date` date DEFAULT NULL,
  `status` enum('planned','on_track','completed','delayed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'on_track',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `survey_follow_up_actions_survey_period_id_foreign` (`survey_period_id`),
  KEY `survey_follow_up_actions_recommendation_id_foreign` (`recommendation_id`),
  CONSTRAINT `survey_follow_up_actions_recommendation_id_foreign` FOREIGN KEY (`recommendation_id`) REFERENCES `survey_recommendations` (`id`) ON DELETE SET NULL,
  CONSTRAINT `survey_follow_up_actions_survey_period_id_foreign` FOREIGN KEY (`survey_period_id`) REFERENCES `survey_periods` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

