DROP TABLE IF EXISTS `survey_responses`;
CREATE TABLE `survey_responses` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `survey_period_id` bigint unsigned NOT NULL,
  `respondent_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `respondent_phone` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `respondent_domicile` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `respondent_age` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `respondent_gender` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `respondent_education` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `respondent_job` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `service_accessed` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ikm_score` decimal(5,2) NOT NULL DEFAULT '0.00',
  `suggestion` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `survey_responses_survey_period_id_foreign` (`survey_period_id`),
  CONSTRAINT `survey_responses_survey_period_id_foreign` FOREIGN KEY (`survey_period_id`) REFERENCES `survey_periods` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=20 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

