DROP TABLE IF EXISTS `survey_result_statistics`;
CREATE TABLE `survey_result_statistics` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `survey_period_id` bigint unsigned NOT NULL,
  `total_respondents` int NOT NULL DEFAULT '0',
  `average_score` decimal(4,2) NOT NULL DEFAULT '0.00',
  `ikm_value` decimal(5,2) NOT NULL DEFAULT '0.00',
  `service_quality_category` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'B',
  `index_breakdown_json` json DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `survey_result_statistics_survey_period_id_unique` (`survey_period_id`),
  CONSTRAINT `survey_result_statistics_survey_period_id_foreign` FOREIGN KEY (`survey_period_id`) REFERENCES `survey_periods` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `survey_result_statistics` (`id`, `survey_period_id`, `total_respondents`, `average_score`, `ikm_value`, `service_quality_category`, `index_breakdown_json`, `created_at`, `updated_at`) VALUES ('1', '1', '8', '3.65', '91.27', 'A', '[{\"category\": \"Persyaratan Pelayanan\", \"ikm_unsur\": 100, \"question_id\": 1, \"question_text\": \"Bagaimana pendapat Anda tentang kesesuaian persyaratan pelayanan dengan jenis pelayanannya?\", \"average_rating\": 4}, {\"category\": \"Prosedur Pelayanan\", \"ikm_unsur\": 96.43, \"question_id\": 2, \"question_text\": \"Bagaimana kemudahan prosedur pelayanan administrasi kependudukan di loket maupun online?\", \"average_rating\": 3.86}, {\"category\": \"Waktu Pelayanan\", \"ikm_unsur\": 78.57, \"question_id\": 3, \"question_text\": \"Bagaimana kecepatan waktu dalam memberikan pelayanan dan penyelesaian dokumen kependudukan?\", \"average_rating\": 3.14}, {\"category\": \"Biaya/Tarif\", \"ikm_unsur\": 96.43, \"question_id\": 4, \"question_text\": \"Bagaimana kepastian dan kejelasan biaya pelayanan (Gratis Rp 0,- sesuai undang-undang)?\", \"average_rating\": 3.86}, {\"category\": \"Produk Spesifikasi\", \"ikm_unsur\": 100, \"question_id\": 5, \"question_text\": \"Bagaimana kesesuaian antara produk hasil pelayanan yang diterima dengan ketentuan yang ditetapkan?\", \"average_rating\": 4}, {\"category\": \"Kompetensi Pelaksana\", \"ikm_unsur\": 75, \"question_id\": 6, \"question_text\": \"Bagaimana kompetensi, keahlian, dan ketrampilan petugas dalam memberikan pelayanan?\", \"average_rating\": 3}, {\"category\": \"Perilaku Pelaksana\", \"ikm_unsur\": 100, \"question_id\": 7, \"question_text\": \"Bagaimana perilaku petugas meliputi kesopanan, keramahan, dan kesiapsiagaan dalam merespon pemohon?\", \"average_rating\": 4}, {\"category\": \"Penanganan Pengaduan\", \"ikm_unsur\": 100, \"question_id\": 8, \"question_text\": \"Bagaimana penanganan pengaduan, saran, dan masukan pengguna layanan kependudukan?\", \"average_rating\": 4}, {\"category\": \"Sarana & Prasarana\", \"ikm_unsur\": 75, \"question_id\": 9, \"question_text\": \"Bagaimana kualitas dan kenyamanan sarana serta prasarana gedung/ruang tunggu pelayanan?\", \"average_rating\": 3}]', '2026-07-23 15:37:07', '2026-07-27 15:45:26');
