INSERT INTO `website_settings` (`id`, `key`, `value`, `group`, `created_at`, `updated_at`) VALUES ('86', 'profile_maklumat_title', '\"Dengan Ini, Kami Menyatakan Sanggup Menyenggarakan Pelayanan Sesuai Standar Pelayanan Yang Telah Ditetapkan\"', 'profil_instansi', '2026-07-27 12:26:35', '2026-07-27 12:26:35');
INSERT INTO `website_settings` (`id`, `key`, `value`, `group`, `created_at`, `updated_at`) VALUES ('87', 'profile_maklumat_subtitle', 'Apabila tidak memenuhi janji ini, kami siap menerima sanksi sesuai dengan peraturan perundang-undangan yang berlaku.', 'profil_instansi', '2026-07-27 12:26:35', '2026-07-27 12:26:35');
INSERT INTO `website_settings` (`id`, `key`, `value`, `group`, `created_at`, `updated_at`) VALUES ('88', 'profile_about_title', 'Tentang Dinas', 'profil_instansi', '2026-07-27 12:34:32', '2026-07-27 12:34:32');
INSERT INTO `website_settings` (`id`, `key`, `value`, `group`, `created_at`, `updated_at`) VALUES ('89', 'profile_about_subtitle', 'Gambaran Umum & Peran Strategis Instansi', 'profil_instansi', '2026-07-27 12:34:32', '2026-07-27 12:34:32');
INSERT INTO `website_settings` (`id`, `key`, `value`, `group`, `created_at`, `updated_at`) VALUES ('90', 'profile_about_content', 'Dinas Kependudukan dan Pencatatan Sipil (Dukcapil) Kabupaten Dompu merupakan instansi pemerintah daerah yang bertugas menyelenggarakan urusan pemerintahan di bidang administrasi kependudukan dan pencatatan sipil di wilayah Kabupaten Dompu, Nusa Tenggara Barat.

Melalui integrasi Sistem Informasi Administrasi Kependudukan (SIAK) Terpusat dan Identitas Kependudukan Digital (IKD), Dukcapil Kabupaten Dompu terus berinovasi untuk menghadirkan pelayanan publik yang melayani tanpa diskriminasi, cepat, akurat, dan Bebas Pungutan Liar (Rp 0,-).', 'profil_instansi', '2026-07-27 12:34:32', '2026-07-27 14:16:25');
INSERT INTO `website_settings` (`id`, `key`, `value`, `group`, `created_at`, `updated_at`) VALUES ('91', 'profile_duties_items', '[{\"title\":\"Tugas Pokok\",\"desc\":\"Melaksanakan urusan pemerintahan di bidang administrasi kependudukan dan pencatatan sipil, meliputi aspek fasilitasi pelayanan administrasi kependudukan serta pengelolaan informasi administrasi kependudukan dan pemanfaatan data.\"},{\"title\":\"Fungsi\",\"desc\":\"Dalam menyelenggarakan tugas pokok, Dinas Kependudukan dan Pencatatan Sipil menyelenggarakan fungsi:\\r\\n1. Penyelenggaraan perumusan kebijakan teknis di bidang administrasi kependudukan dan pencatatan sipil.\\r\\n2. Penyelenggaraan pelayanan administrasi kependudukan dan pencatatan sipil.\\r\\n3. Penyelenggaraan evaluasi, pelaporan, dan pengendalian sistem informasi.\\r\\n4. Penyelenggaraan fungsi dinas lainnya sesuai tugas pokok dan fungsinya.\"},{\"title\":\"Kewenangan Disdukcapil Kabupaten Dompu\",\"desc\":\"Pemerintah Kabupaten berkewajiban dan bertanggung jawab menyelenggarakan urusan Administrasi Kependudukan dengan kewenangan meliputi:\\r\\n1. Koordinasi penyelenggaraan Administrasi Kependudukan.\\r\\n2. Pemberian bimbingan, supervisi, dan konsultasi pelaksanaan Pendaftaran Penduduk dan Pencatatan Sipil.\\r\\n3. Pembinaan dan sosialisasi penyelenggaraan Administrasi Kependudukan.\\r\\n4. Penyajian Data Kependudukan berskala Kabupaten dari SIAK Terpusat.\\r\\n5. Koordinasi pengawasan atas penyelenggaraan Administrasi Kependudukan.\"}]', 'profil_instansi', '2026-07-27 12:36:15', '2026-07-27 14:24:56');

